    // ─── v4.10.0 (CIRISPersist#154, CEG 0.8 §0.8.1) — location proof ───

    /// A valid res-7 cell admits + round-trips; an over-precise (res-9)
    /// proof is refused at admission (§0.8.1 rough-only); a malformed cell
    /// is refused; the FK to federation_keys holds.
    #[tokio::test]
    async fn location_proof_round_trip_and_rough_only_gate() {
        use crate::federation::LocationProof;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("subj", "subj", "subj"),
            })
            .await
            .unwrap();

        let ll = h3o::LatLng::new(37.0, -122.0).unwrap();
        let cell7 = ll.to_cell(h3o::Resolution::Seven).to_string();
        // #502 E4 — `asserted_at` is a parameter (not post-hoc mutated) so the
        // signature below is always computed over the EXACT stored envelope.
        let proof = |cell: &str, res: u8, asserted_at: &str| {
            crate::federation::tier_ingest::test_support::sign_location_proof(
                "subj",
                LocationProof {
                    subject_key_id: "subj".into(),
                    cell_id: cell.into(),
                    cell_resolution: res,
                    asserted_at: asserted_at.parse().unwrap(),
                    valid_until: None,
                    attestation_evidence: None,
                    withdrawn_at: None,
                    persist_row_hash: String::new(),
                },
            )
        };

        // Valid res-7 admits + round-trips.
        backend
            .put_location_proof(proof(&cell7, 7, "2026-06-09T00:00:00Z"))
            .await
            .unwrap();
        let rows = backend.list_location_proofs_for("subj").await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].cell_id, cell7);
        assert_eq!(rows[0].cell_resolution, 7);
        assert!(!rows[0].persist_row_hash.is_empty(), "hash computed");

        // Over-precise res-9 → refused (§0.8.1 rough-only).
        let cell9 = ll.to_cell(h3o::Resolution::Nine).to_string();
        let input = proof(&cell9, 9, "2026-06-09T01:00:00Z");
        let err = backend.put_location_proof(input).await.unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("rough-only")),
            "got: {err:?}"
        );
        // Malformed cell → refused.
        let bad = proof("not-a-cell", 7, "2026-06-09T02:00:00Z");
        assert!(backend.put_location_proof(bad).await.is_err());

        // Still exactly one stored row (rejections didn't write).
        assert_eq!(
            backend
                .list_location_proofs_for("subj")
                .await
                .unwrap()
                .len(),
            1
        );
    }

    /// CIRISPersist#210 — full SharedInstanceLease lifecycle: acquire,
    /// live-contention rejection, lookup, heartbeat, stale-steal (version
    /// bump), demotion detection, ownership-checked release.
    #[tokio::test]
    async fn shared_instance_lease_election_lifecycle() {
        use std::time::Duration;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let name = "reticulum:default";

        // 1. Acquire on an empty slot → win, version 1.
        let lease = backend
            .try_acquire_shared_instance(name, 1001, "hostA", None)
            .await
            .unwrap()
            .expect("first acquire wins");
        assert_eq!(lease.owner_pid, 1001);
        assert_eq!(lease.lease_version, 1);
        assert_eq!(lease.instance_name, name);

        // 2. A second, live contender → loses (None).
        assert!(
            backend
                .try_acquire_shared_instance(name, 2002, "hostB", None)
                .await
                .unwrap()
                .is_none(),
            "a live owner blocks a second acquirer"
        );

        // 3. lookup reports the owner.
        let found = backend
            .lookup_shared_instance_lease(name)
            .await
            .unwrap()
            .unwrap();
        assert_eq!((found.owner_pid, found.lease_version), (1001, 1));

        // 4. Owner heartbeats → still owner, same version, fresher beat.
        let beat = backend
            .heartbeat_shared_instance(&lease)
            .await
            .unwrap()
            .expect("owner still holds");
        assert_eq!((beat.owner_pid, beat.lease_version), (1001, 1));
        assert!(beat.last_heartbeat_at >= lease.last_heartbeat_at);

        // 5. Let the heartbeat age, then steal with a small stale window.
        tokio::time::sleep(Duration::from_millis(40)).await;
        let stolen = backend
            .try_acquire_shared_instance(name, 2002, "hostB", Some(Duration::from_millis(10)))
            .await
            .unwrap()
            .expect("a stale owner is stealable");
        assert_eq!(stolen.owner_pid, 2002);
        assert_eq!(stolen.lease_version, 2, "steal increments the version");

        // 6. The demoted original owner's heartbeat → None (takeover seen).
        assert!(
            backend
                .heartbeat_shared_instance(&beat)
                .await
                .unwrap()
                .is_none(),
            "original owner learns its lease was stolen"
        );

        // 7. Owner releases → row gone; next acquire is fresh at v1.
        backend
            .release_shared_instance_lease(&stolen)
            .await
            .unwrap();
        assert!(backend
            .lookup_shared_instance_lease(name)
            .await
            .unwrap()
            .is_none());
        let fresh = backend
            .try_acquire_shared_instance(name, 3003, "hostC", None)
            .await
            .unwrap()
            .expect("acquire after release wins");
        assert_eq!(fresh.lease_version, 1, "released slot → fresh lease at v1");

        // 8. A stale (non-current) release must NOT evict the live owner.
        backend
            .release_shared_instance_lease(&stolen)
            .await
            .unwrap();
        assert!(
            backend
                .lookup_shared_instance_lease(name)
                .await
                .unwrap()
                .is_some(),
            "stale release never deletes another process's current lease"
        );
    }

    /// v4.11.0 (#154 Ask 4/5) — geographic community admission gates each
    /// member on an in-force contained location_proof; `communities_
    /// containing` finds the community for a cell inside its constraint.
    #[tokio::test]
    async fn geographic_community_admission_and_containing() {
        use crate::federation::{Community, CommunityMember, LocationProof};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["geo-comm", "alice", "bob"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        let ll = h3o::LatLng::new(37.0, -122.0).unwrap();
        let constraint = ll.to_cell(h3o::Resolution::Three).to_string();
        let inside = ll.to_cell(h3o::Resolution::Seven).to_string();

        // alice has an in-force contained proof; bob has none.
        backend
            .put_location_proof(
                crate::federation::tier_ingest::test_support::sign_location_proof(
                    "alice",
                    LocationProof {
                        subject_key_id: "alice".into(),
                        cell_id: inside.clone(),
                        cell_resolution: 7,
                        asserted_at: "2026-06-01T00:00:00Z".parse().unwrap(),
                        valid_until: None,
                        attestation_evidence: None,
                        withdrawn_at: None,
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();

        let geo_policy = serde_json::json!({
            "cohort_subkind": "geographic",
            "geographic_constraint": {"cell_id": constraint, "cell_resolution": 3}
        });
        let community = |members: Vec<&str>| {
            crate::federation::tier_ingest::test_support::sign_community(
                "geo-comm",
                Community {
                    community_key_id: "geo-comm".into(),
                    community_name: "Geo".into(),
                    members: members
                        .into_iter()
                        .map(|k| CommunityMember {
                            key_id: k.into(),
                            joined_at: "2026-06-01T00:00:00Z".parse().unwrap(),
                            role: None,
                        })
                        .collect(),
                    founded_at: "2026-06-01T00:00:00Z".parse().unwrap(),
                    consensus_protocol: "unanimous".into(),
                    policy_blob: Some(geo_policy.clone()),
                    persist_row_hash: String::new(),
                },
            )
        };

        // bob (no contained proof) → refused.
        let err = backend
            .put_community(community(vec!["alice", "bob"]))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("location_proof")),
            "got: {err:?}"
        );
        // alice-only → admits.
        backend
            .put_community(community(vec!["alice"]))
            .await
            .unwrap();

        // communities_containing: a cell inside the constraint finds it.
        let hit = backend.communities_containing(&inside).await.unwrap();
        assert_eq!(hit.len(), 1);
        assert_eq!(hit[0].community_key_id, "geo-comm");
        // A far-away cell does not.
        let far = h3o::LatLng::new(-33.8, 151.2)
            .unwrap()
            .to_cell(h3o::Resolution::Seven)
            .to_string();
        assert!(backend
            .communities_containing(&far)
            .await
            .unwrap()
            .is_empty());
    }

    // ─── v4.8.0 (CIRISPersist#161, CEG §11.7.1) — revocation tests ─────

    /// Revocation round-trip + active-state filtering: a past-effective
    /// occurrence revocation excludes the binding from
    /// `list_identity_occurrences_active`; a future-effective one does
    /// NOT. Family/community removals filter `list_*_for_member_active`.
    #[tokio::test]
    async fn membership_revocation_round_trip_and_active_filtering() {
        use crate::federation::{FamilyMembershipRevocation, IdentityOccurrenceRevocation};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in [
            "alice-root",
            "alice-phone",
            "alice-laptop",
            "fam-1",
            "bob-root",
        ] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        // Two occurrences of alice-root.
        for occ in ["alice-phone", "alice-laptop"] {
            backend
                .put_identity_occurrence_local(fed_identity_occurrence(
                    "alice-root",
                    occ,
                    crate::federation::types::device_class::PHONE,
                ))
                .await
                .unwrap();
        }
        // Family with alice-root + bob-root.
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "fam-1",
                fed_family("fam-1", "Fam", vec!["alice-root", "bob-root"], "unanimous"),
            ))
            .await
            .unwrap();

        // Revoke alice-phone, effective in the past (trusted-local, #421).
        backend
            .put_identity_occurrence_revocation_local(IdentityOccurrenceRevocation {
                identity_key_id: "alice-root".into(),
                occurrence_key_id: "alice-phone".into(),
                revoked_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                effective_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                reason: Some("lost device".into()),
                witness_set: vec!["alice-root".into()],
                persist_row_hash: String::new(),
            })
            .await
            .unwrap();

        // list_*_revocations_for round-trips the row.
        let revs = backend
            .list_identity_occurrence_revocations_for("alice-root")
            .await
            .unwrap();
        assert_eq!(revs.len(), 1);
        assert_eq!(revs[0].occurrence_key_id, "alice-phone");
        assert_eq!(revs[0].witness_set, vec!["alice-root".to_string()]);
        assert!(!revs[0].persist_row_hash.is_empty(), "hash computed");

        // active excludes the revoked occurrence; _for keeps both (history).
        let active = backend
            .list_identity_occurrences_active("alice-root")
            .await
            .unwrap();
        let active_ids: Vec<_> = active
            .iter()
            .map(|o| o.occurrence_key_id.as_str())
            .collect();
        assert_eq!(active_ids, vec!["alice-laptop"], "revoked phone excluded");
        assert_eq!(
            backend
                .list_identity_occurrences_for("alice-root")
                .await
                .unwrap()
                .len(),
            2,
            "_for is the full-history accessor"
        );

        // Future-effective revocation does NOT exclude (trusted-local, #421).
        backend
            .put_identity_occurrence_revocation_local(IdentityOccurrenceRevocation {
                identity_key_id: "alice-root".into(),
                occurrence_key_id: "alice-laptop".into(),
                revoked_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                effective_at: "2099-01-01T00:00:00Z".parse().unwrap(),
                reason: None,
                witness_set: vec![],
                persist_row_hash: String::new(),
            })
            .await
            .unwrap();
        let active = backend
            .list_identity_occurrences_active("alice-root")
            .await
            .unwrap();
        assert_eq!(
            active.len(),
            1,
            "future-dated revocation must not take effect yet"
        );

        // Family removal: bob-root removed, effective in the past.
        backend
            .put_family_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_family_membership_revocation(
                    "fam-1",
                    FamilyMembershipRevocation {
                        family_key_id: "fam-1".into(),
                        removed_identity_key_id: "bob-root".into(),
                        removed_at: "2026-06-06T00:00:00Z".parse().unwrap(),
                        effective_at: "2026-06-06T00:00:00Z".parse().unwrap(),
                        reason: Some("left household".into()),
                        witness_set: vec!["alice-root".into()],
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();
        // bob-root no longer an active member; alice-root still is.
        assert!(
            backend
                .list_families_for_member_active("bob-root")
                .await
                .unwrap()
                .is_empty(),
            "removed member drops out of active families"
        );
        assert_eq!(
            backend
                .list_families_for_member_active("alice-root")
                .await
                .unwrap()
                .len(),
            1,
            "remaining member still active"
        );
        // _for_member (history) still shows bob in the roster.
        assert_eq!(
            backend
                .list_families_for_member("bob-root")
                .await
                .unwrap()
                .len(),
            1
        );
    }

    /// v4.13.0 (#192, CEG 0.18) — occurrence content-encryption pubkeys
    /// round-trip + `resolve_encryption_keys` + admission length-gate.
    #[tokio::test]
    async fn occurrence_encryption_pubkeys_round_trip_and_resolve() {
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["root", "occ-enc", "occ-bare"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        let x25519 = B64.encode([7u8; 32]); // valid 32-byte x25519
        let ml_kem = B64.encode([9u8; 1184]); // valid 1184-byte ML-KEM-768
        let occ = |k: &str, enc: Option<EncryptionPubkeys>| crate::federation::IdentityOccurrence {
            identity_key_id: "root".into(),
            occurrence_key_id: k.into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: "2026-06-10T00:00:00Z".parse().unwrap(),
            valid_until: None,
            encryption_pubkeys: enc,
            transport_binding: None,
            persist_row_hash: String::new(),
        };

        // Occurrence WITH encryption keys → round-trips + resolves.
        backend
            .put_identity_occurrence_local(occ(
                "occ-enc",
                Some(EncryptionPubkeys {
                    x25519_base64: x25519.clone(),
                    ml_kem_768_base64: ml_kem.clone(),
                }),
            ))
            .await
            .unwrap();
        let got = backend
            .lookup_identity_for_occurrence("occ-enc")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            got.encryption_pubkeys,
            Some(EncryptionPubkeys {
                x25519_base64: x25519.clone(),
                ml_kem_768_base64: ml_kem.clone()
            })
        );
        let resolved = backend
            .resolve_encryption_keys("occ-enc")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(resolved.x25519_base64, x25519);
        assert_eq!(resolved.ml_kem_768_base64, ml_kem);

        // Occurrence WITHOUT keys → resolve = None (fail-secure exclusion).
        backend
            .put_identity_occurrence_local(occ("occ-bare", None))
            .await
            .unwrap();
        assert!(backend
            .resolve_encryption_keys("occ-bare")
            .await
            .unwrap()
            .is_none());
        // Unknown occurrence → None.
        assert!(backend
            .resolve_encryption_keys("nope")
            .await
            .unwrap()
            .is_none());

        // Admission rejects a wrong-length key.
        let err = backend
            .put_identity_occurrence_local(occ(
                "occ-enc",
                Some(EncryptionPubkeys {
                    x25519_base64: B64.encode([0u8; 16]), // too short
                    ml_kem_768_base64: ml_kem,
                }),
            ))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("x25519_base64")),
            "got: {err:?}"
        );
    }

    /// v4.14.0 (CIRISPersist#152, CEG 0.18 §10.1.4) — the self/family
    /// at-rest DEK cascade end-to-end on SQLite:
    /// - a `cohort_scope:self` write stores **ciphertext** (≠ plaintext),
    /// - a granted recipient occurrence reads back the plaintext via
    ///   `get_blob_for_viewer` (default tier — persist holds the DEK),
    /// - a non-recipient occurrence gets `NotGranted`,
    /// - a recipient occurrence WITHOUT `encryption_pubkeys` is fail-secure
    ///   EXCLUDED (no grant row, never plaintext),
    /// - an unknown SHA is `NotHeld`.
    #[tokio::test]
    async fn at_rest_self_cascade_round_trip_and_fail_secure() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer,
        };
        use crate::federation::types::cohort_scope::SELF;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // Identity + three occurrences: one with keys (granted), one
        // without keys (fail-secure excluded), one never a recipient.
        for k in ["root", "occ-keyed", "occ-bare", "outsider"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }

        // Real keypairs so the v2 wrap genuinely encapsulates.
        let x_priv: [u8; 32] = [0x42; 32];
        let x_pub = ciris_crypto::x25519::public_from_secret(&x_priv);
        let (_ml_priv, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();

        let occ = |k: &str, enc: Option<EncryptionPubkeys>| crate::federation::IdentityOccurrence {
            identity_key_id: "root".into(),
            occurrence_key_id: k.into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: "2026-06-10T00:00:00Z".parse().unwrap(),
            valid_until: None,
            encryption_pubkeys: enc,
            transport_binding: None,
            persist_row_hash: String::new(),
        };
        backend
            .put_identity_occurrence_local(occ(
                "occ-keyed",
                Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
            ))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(occ("occ-bare", None))
            .await
            .unwrap();

        let plaintext = b"a private note about the cat, scoped to self";
        let result = encrypt_and_cascade(&backend, SELF, "root", plaintext, Some("text/plain"))
            .await
            .unwrap();

        // The keyed occurrence got a grant; the bare one was fail-secure
        // excluded (no plaintext fallback).
        assert_eq!(result.granted, vec!["occ-keyed".to_string()]);
        assert_eq!(result.excluded, vec!["occ-bare".to_string()]);

        // The stored body is CIPHERTEXT (≠ plaintext) and carries the
        // at-rest envelope magic.
        let stored = backend
            .get_blob(&result.at_rest_sha256)
            .await
            .unwrap()
            .expect("at-rest bytes present");
        let stored_bytes = match stored {
            crate::federation::BlobBody::Inline(b) => b,
            other => panic!("expected inline ciphertext, got {other:?}"),
        };
        assert_ne!(stored_bytes, plaintext.to_vec(), "body must be ciphertext");
        assert!(
            crate::federation::at_rest_cascade::AtRestEnvelope::has_magic(&stored_bytes),
            "stored body carries the at-rest envelope marker"
        );

        // NO holds_bytes was emitted (structural invisibility).
        assert!(backend
            .list_local_holders(&result.at_rest_sha256)
            .await
            .unwrap()
            .is_empty());

        // Granted recipient reads the plaintext back (default tier).
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, "occ-keyed")
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // The fail-secure-excluded occurrence has NO grant → NotGranted.
        let bare_err = read_for_viewer(&backend, &result.at_rest_sha256, "occ-bare")
            .await
            .unwrap_err();
        assert!(
            matches!(bare_err, crate::federation::BlobError::NotGranted { .. }),
            "bare occurrence is fail-secure denied, got: {bare_err:?}"
        );

        // A non-recipient gets NotGranted.
        let outsider_err = read_for_viewer(&backend, &result.at_rest_sha256, "outsider")
            .await
            .unwrap_err();
        assert!(matches!(
            outsider_err,
            crate::federation::BlobError::NotGranted { .. }
        ));

        // The fail-secure exclusion left NO grant row for the bare occ.
        let recipients = backend
            .list_at_rest_grant_recipients(&result.at_rest_sha256)
            .await
            .unwrap();
        assert_eq!(recipients, vec!["occ-keyed".to_string()]);

        // An unknown SHA → NotHeld (after a grant check; here there is no
        // grant for the viewer, so NotGranted fires first — assert NotHeld
        // via a viewer that IS granted on the real blob but a bogus sha).
        let bogus = [0u8; 32];
        let nh = read_for_viewer(&backend, &bogus, "occ-keyed")
            .await
            .unwrap_err();
        assert!(
            matches!(nh, crate::federation::BlobError::NotGranted { .. }),
            "no grant for bogus sha → NotGranted, got: {nh:?}"
        );
    }

    /// v4.14.0 (CIRISPersist#152) — the `cohort_scope:family` cascade:
    /// every active occurrence of every current family member identity
    /// gets a grant; a member identity with no keyed occurrence is
    /// fail-secure excluded.
    #[tokio::test]
    async fn at_rest_family_cascade_grants_every_member_occurrence() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer,
        };
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // Two member identities (alice, bob) + the family key. alice has a
        // keyed occurrence; bob has a bare (keyless) occurrence.
        for k in ["fam", "alice", "bob", "alice-phone", "bob-phone"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        let x_pub = ciris_crypto::x25519::public_from_secret(&[0x55; 32]);
        let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();

        let occ = |identity: &str, occ_key: &str, enc: Option<EncryptionPubkeys>| {
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: "2026-06-10T00:00:00Z".parse().unwrap(),
                valid_until: None,
                encryption_pubkeys: enc,
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        backend
            .put_identity_occurrence_local(occ(
                "alice",
                "alice-phone",
                Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
            ))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(occ("bob", "bob-phone", None))
            .await
            .unwrap();

        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "fam",
                fed_family("fam", "Household", vec!["alice", "bob"], "unanimous"),
            ))
            .await
            .unwrap();

        let plaintext = b"family grocery list";
        let result = encrypt_and_cascade(&backend, FAMILY, "fam", plaintext, None)
            .await
            .unwrap();

        // alice-phone (keyed) granted; bob-phone (bare) excluded.
        assert_eq!(result.granted, vec!["alice-phone".to_string()]);
        assert_eq!(result.excluded, vec!["bob-phone".to_string()]);

        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, "alice-phone")
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        let bob_err = read_for_viewer(&backend, &result.at_rest_sha256, "bob-phone")
            .await
            .unwrap_err();
        assert!(matches!(
            bob_err,
            crate::federation::BlobError::NotGranted { .. }
        ));
    }

    // ── v9.0.0 G5 (CC 4.4.3.2.1 / 4.4.3.2.2) community DEK cascade ─────

    /// Helper: register identity keys + keyed/keyless occurrences + a
    /// community, returning the backend. `members` is `(identity, occ,
    /// keyed?)`. `policy` carries the optional cohort_subkind.
    async fn community_fixture(
        members: &[(&str, &str, bool)],
        policy: Option<serde_json::Value>,
    ) -> SqliteBackend {
        // SecReview F2: an infrastructure-labeled community is only honored
        // when its OWN key is the `substrate_persist` governance authority.
        // Default the comm key's authority to "authorized" exactly when the
        // fixture is infra-labeled (keeps the authorized-carve-out tests
        // exercising the honored path); a non-infra fixture's comm key
        // identity_type is irrelevant to the gate.
        let comm_is_infra = policy
            .as_ref()
            .and_then(|b| b.get("cohort_subkind"))
            .and_then(|v| v.as_str())
            == Some("infrastructure");
        community_fixture_comm_authority(members, policy, comm_is_infra).await
    }

    /// As [`community_fixture`] but with explicit control over whether the
    /// community's OWN key carries the `substrate_persist` governance
    /// authority — used by the SecReview F2 unauthorized-infra-label test
    /// (infra-labeled but `comm_authorized == false`).
    async fn community_fixture_comm_authority(
        members: &[(&str, &str, bool)],
        policy: Option<serde_json::Value>,
        comm_authorized: bool,
    ) -> SqliteBackend {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let mut comm_key = fed_key("comm", "comm", "comm");
        if comm_authorized {
            comm_key.identity_type =
                crate::federation::types::identity_type::SUBSTRATE_PERSIST.into();
        }
        backend
            .put_public_key(SignedKeyRecord { record: comm_key })
            .await
            .unwrap();
        let mut member_idents = Vec::new();
        for (ident, occ, keyed) in members {
            for k in [*ident, *occ] {
                backend
                    .put_public_key(SignedKeyRecord {
                        record: fed_key(k, ident, k),
                    })
                    .await
                    .unwrap();
            }
            let enc = if *keyed {
                Some(keyed_enc(occ.len() as u8 + 1))
            } else {
                None
            };
            backend
                .put_identity_occurrence_local(occ_signed(ident, occ, enc))
                .await
                .unwrap();
            member_idents.push(*ident);
        }
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    "comm",
                    fed_community(
                        "comm",
                        "Test Co-op",
                        member_idents,
                        crate::federation::types::consensus_protocol::MAJORITY,
                        policy,
                    ),
                ),
            )
            .await
            .unwrap();
        backend
    }

    fn comm_revoke(
        removed: &str,
        effective: &str,
    ) -> crate::federation::SignedCommunityMembershipRevocation {
        crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
            "comm",
            crate::federation::CommunityMembershipRevocation {
                community_key_id: "comm".into(),
                removed_identity_key_id: removed.into(),
                removed_at: effective.parse().unwrap(),
                effective_at: effective.parse().unwrap(),
                reason: Some("left".into()),
                witness_set: vec![],
                persist_row_hash: String::new(),
            },
        )
    }

    /// Non-infra community with at-rest enabled → a v2 key_grant per member
    /// with valid ML-KEM-768; a keyless member is EXCLUDED + a
    /// hard_case:recipient_excluded is emitted (NOT plaintext, NOT v1).
    #[tokio::test]
    async fn community_dek_cascade_grants_members_excludes_keyless_sqlite() {
        use crate::federation::community_dek::orchestrate::{
            emit_excluded_hard_cases, encrypt_and_cascade_community, read_for_community_viewer,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::{BlobStorage, FederationDirectory};

        let backend = community_fixture(
            &[("alice", "alice-occ", true), ("bob", "bob-occ", false)],
            None,
        )
        .await;

        let plaintext = b"co-op meeting minutes";
        let result = encrypt_and_cascade_community(&backend, "comm", plaintext, Some("text/plain"))
            .await
            .unwrap();
        assert_eq!(
            result.epoch, 0,
            "never-rotated community seals under epoch 0"
        );
        assert_eq!(result.granted, vec!["alice-occ".to_string()]);
        assert_eq!(result.excluded, vec!["bob-occ".to_string()]);

        // Granted member's grant exists and is v2; keyless member has NONE.
        let recips = backend
            .community_dek_member_grant_recipients("comm", 0)
            .await
            .unwrap();
        assert_eq!(recips, vec!["alice-occ".to_string()]);
        assert!(backend
            .community_dek_has_member_grant("comm", 0, "alice-occ")
            .await
            .unwrap());
        assert!(!backend
            .community_dek_has_member_grant("comm", 0, "bob-occ")
            .await
            .unwrap());

        // The keyed member reads; the excluded one cannot (no plaintext).
        assert_eq!(
            read_for_community_viewer(&backend, &result.at_rest_sha256, "alice-occ")
                .await
                .unwrap(),
            plaintext
        );
        assert!(matches!(
            read_for_community_viewer(&backend, &result.at_rest_sha256, "bob-occ")
                .await
                .unwrap_err(),
            crate::federation::BlobError::NotGranted { .. }
        ));

        // hard_case:recipient_excluded emitted for the keyless member.
        emit_excluded_hard_cases(&backend, &result, chrono::Utc::now())
            .await
            .unwrap();
        let events = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(events
            .iter()
            .any(|e| e.subject_key_id.as_deref() == Some("bob-occ")));
    }

    /// A cohort_subkind:infrastructure community opts OUT of the DEK
    /// cascade entirely (CC 4.4.3.2.1) — the cascade REFUSES to run, so the
    /// caller stores plaintext via the ordinary path. No DEK row is written.
    #[tokio::test]
    async fn community_dek_infrastructure_opts_out_sqlite() {
        use crate::federation::community_dek::orchestrate::encrypt_and_cascade_community;
        use crate::federation::BlobStorage;

        let backend = community_fixture(
            &[("alice", "alice-occ", true)],
            Some(serde_json::json!({ "cohort_subkind": "infrastructure" })),
        )
        .await;

        let err = encrypt_and_cascade_community(&backend, "comm", b"canonical root", None)
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::BlobError::InvalidArgument(_)
        ));
        // No epoch-0 DEK was minted for the infra community.
        assert!(backend
            .community_dek_get_self_retention("comm", 0)
            .await
            .unwrap()
            .is_none());
    }

    /// SecReview F2: an `infrastructure`-LABELED community whose own key is
    /// NOT `substrate_persist` is NOT exempted — the DEK cascade STILL runs
    /// (fail-secure: a self-applied infra label can never force content to
    /// Commons-plaintext). The cascade succeeds + mints an epoch-0 DEK
    /// instead of refusing.
    #[tokio::test]
    async fn community_dek_unauthorized_infra_label_still_cascades_sqlite() {
        use crate::federation::community_dek::orchestrate::encrypt_and_cascade_community;
        use crate::federation::BlobStorage;

        // Infra-LABELED community whose own key is NOT substrate_persist
        // (comm_authorized == false) — an UNauthorized self-labeled infra.
        let backend = community_fixture_comm_authority(
            &[("alice", "alice-occ", true)],
            Some(serde_json::json!({ "cohort_subkind": "infrastructure" })),
            false,
        )
        .await;

        // The cascade does NOT refuse — it seals under a real DEK.
        let result =
            encrypt_and_cascade_community(&backend, "comm", b"not actually canonical", None)
                .await
                .expect("unauthorized infra label must NOT opt out of the DEK cascade");
        assert_eq!(result.epoch, 0);
        assert_eq!(result.granted, vec!["alice-occ".to_string()]);
        // An epoch-0 DEK self-retention row WAS minted (cascade ran).
        assert!(backend
            .community_dek_get_self_retention("comm", 0)
            .await
            .unwrap()
            .is_some());
    }

    /// SecReview F4: a FUTURE-DATED community membership revocation
    /// `effective_at` is REJECTED before any write; a non-future one is
    /// accepted AND bumps the DEK epoch (sqlite parity).
    #[tokio::test]
    async fn community_revocation_rejects_future_dated_effective_at_sqlite() {
        use crate::federation::BlobStorage;
        let backend = community_fixture(
            &[("alice", "alice-occ", true), ("bob", "bob-occ", true)],
            None,
        )
        .await;
        let rev = |effective: chrono::DateTime<chrono::Utc>| {
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                "comm",
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: "comm".into(),
                    removed_identity_key_id: "bob".into(),
                    removed_at: effective,
                    effective_at: effective,
                    reason: Some("left".into()),
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            )
        };
        let future = chrono::Utc::now() + chrono::Duration::days(30);
        let err = backend
            .put_community_membership_revocation(rev(future))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(_)),
            "future-dated effective_at must be rejected, got {err:?}"
        );
        // No bump on rejection.
        assert_eq!(
            backend.community_dek_current_epoch("comm").await.unwrap(),
            0
        );
        // Non-future revocation accepted → epoch bumps.
        backend
            .put_community_membership_revocation(rev(chrono::Utc::now()))
            .await
            .expect("non-future revocation accepted");
        assert_eq!(
            backend.community_dek_current_epoch("comm").await.unwrap(),
            1
        );
    }

    /// CC 4.4.3.2.8 / #308 — the `affiliations` cohort runs the full membership
    /// lifecycle (add → active-members → revoke + epoch bump) through the SAME
    /// community machinery on the SQLite backend (pg/sqlite/memory parity).
    #[tokio::test]
    async fn affiliations_cohort_membership_lifecycle_sqlite() {
        use crate::federation::cohort::{Cohort, RosterMember};
        use crate::federation::{BlobStorage, FederationDirectory};
        let backend = community_fixture(&[("alice", "alice-occ", true)], None).await;
        // Register a fresh PRIMITIVE key to admit via the affiliations cohort.
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("carol", "carol", "carol"),
            })
            .await
            .unwrap();

        let added = backend
            .add_member(
                Cohort::Affiliations,
                "comm",
                RosterMember {
                    key_id: "carol".into(),
                    joined_at: chrono::Utc::now(),
                    role: Some("member".into()),
                },
            )
            .await
            .expect("affiliations add_member");
        assert!(added);

        let active: Vec<String> = backend
            .active_members(Cohort::Affiliations, "comm")
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(active.contains(&"carol".to_string()));
        // Shared roster: reading via `community` is identical.
        let via_community: Vec<String> = backend
            .active_members(Cohort::Community, "comm")
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert_eq!(active, via_community);

        assert_eq!(
            backend.community_dek_current_epoch("comm").await.unwrap(),
            0
        );
        backend
            .revoke_member(
                Cohort::Affiliations,
                "comm",
                "carol",
                crate::federation::tier_ingest::test_support::sign_revoke_spec(
                    Cohort::Affiliations,
                    "comm",
                    "comm",
                    "carol",
                    chrono::Utc::now(),
                    Some("left".into()),
                    vec![],
                ),
            )
            .await
            .expect("affiliations revoke_member");
        assert_eq!(
            backend.community_dek_current_epoch("comm").await.unwrap(),
            1,
            "affiliations removal bumps the CommunityDek epoch (forward secrecy)"
        );
        let active_after: Vec<String> = backend
            .active_members(Cohort::Affiliations, "comm")
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(!active_after.contains(&"carol".to_string()));
    }

    /// #249 Cut A — the JSON-shape contract the FFI active-variant
    /// wrappers (`list_communities_for_member_active_json` /
    /// `list_families_for_member_active_json`) expose to pyo3 consumers:
    /// seed a community + an effective membership revocation, then assert
    /// the serde_json serialization of `list_communities_for_member_active`
    /// (exactly what the wrapper returns) EXCLUDES the revoked member while
    /// the full-history `list_communities_for_member` still includes them.
    /// This is the "stop hand-folding revocations" property — proven at the
    /// serialized boundary the UI consumes, not just the typed Rust level.
    #[tokio::test]
    async fn cut_a_active_community_json_excludes_revoked_member_sqlite() {
        use crate::federation::{Community, FederationDirectory};
        let backend = community_fixture(
            &[("alice", "alice-occ", true), ("bob", "bob-occ", true)],
            None,
        )
        .await;

        // Pre-revocation: both alice and bob see the community in their
        // active list, and the JSON array carries one Community.
        for member in ["alice", "bob"] {
            let active = backend
                .list_communities_for_member_active(member)
                .await
                .unwrap();
            let json = serde_json::to_string(&active).unwrap();
            let parsed: Vec<Community> = serde_json::from_str(&json).unwrap();
            assert_eq!(parsed.len(), 1, "{member} active before revocation");
            assert_eq!(parsed[0].community_key_id, "comm");
        }

        // Remove bob, effective in the past.
        backend
            .put_community_membership_revocation(comm_revoke("bob", "2026-06-10T00:00:00Z"))
            .await
            .unwrap();

        // Active list (the FFI wrapper's payload) now EXCLUDES bob via the
        // serialized JSON shape...
        let bob_active = backend
            .list_communities_for_member_active("bob")
            .await
            .unwrap();
        let bob_json = serde_json::to_string(&bob_active).unwrap();
        let bob_parsed: Vec<Community> = serde_json::from_str(&bob_json).unwrap();
        assert!(
            bob_parsed.is_empty(),
            "active JSON must drop the revoked member, got {bob_json}"
        );

        // ...while the full-history reader still lists the community for bob
        // (the `_json` wrapper of `list_communities_for_member` is unchanged).
        let bob_history = backend.list_communities_for_member("bob").await.unwrap();
        assert_eq!(
            bob_history.len(),
            1,
            "full-history reader is unaffected by the revocation"
        );

        // alice (not revoked) stays in the active JSON.
        let alice_active = backend
            .list_communities_for_member_active("alice")
            .await
            .unwrap();
        let alice_parsed: Vec<Community> =
            serde_json::from_str(&serde_json::to_string(&alice_active).unwrap()).unwrap();
        assert_eq!(alice_parsed.len(), 1, "remaining member stays active");

        // The community-membership revocation reader (the
        // `list_community_membership_revocations_for_json` payload) carries
        // exactly the one bob removal.
        let revs = backend
            .list_community_membership_revocations_for("comm")
            .await
            .unwrap();
        let revs_parsed: Vec<crate::federation::CommunityMembershipRevocation> =
            serde_json::from_str(&serde_json::to_string(&revs).unwrap()).unwrap();
        assert_eq!(revs_parsed.len(), 1);
        assert_eq!(revs_parsed[0].removed_identity_key_id, "bob");

        // lookup_community (the `lookup_community_json` payload) round-trips
        // through JSON and carries the full roster (revocation is a separate
        // table; the roster itself is untouched).
        let looked = backend.lookup_community("comm").await.unwrap();
        let looked_json = serde_json::to_string(&looked).unwrap();
        let looked_parsed: Option<Community> = serde_json::from_str(&looked_json).unwrap();
        let community = looked_parsed.expect("community present");
        assert_eq!(community.community_key_id, "comm");
        assert_eq!(community.members.len(), 2, "roster intact post-revocation");
    }

    /// SecReview F5: INSERT + hard_case + epoch-bump are ONE transaction —
    /// if the epoch bump fails, the revocation INSERT is rolled back (no
    /// durable un-rotated revocation). Induce the bump failure by dropping
    /// the epoch table out from under the call, then assert NEITHER the
    /// revocation row NOR a hard_case event was committed.
    #[tokio::test]
    async fn community_revocation_atomic_on_bump_failure_sqlite() {
        use crate::federation::hard_case::{kind, HardCaseFilter};
        let backend = community_fixture(
            &[("alice", "alice-occ", true), ("bob", "bob-occ", true)],
            None,
        )
        .await;
        // Drop the epoch table so the in-transaction bump statement errors.
        backend
            .conn_handle()
            .lock()
            .execute("DROP TABLE federation_community_dek_epoch", [])
            .unwrap();

        let err = backend
            .put_community_membership_revocation(comm_revoke("bob", "2026-06-10T00:00:00Z"))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::Backend(_)),
            "bump failure should surface, got {err:?}"
        );
        // The revocation INSERT rolled back — no durable revocation row.
        assert!(backend
            .list_community_membership_revocations_for("comm")
            .await
            .unwrap()
            .is_empty());
        // And no hard_case event was committed either.
        let events = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::COMMUNITY_MEMBERSHIP_CHANGE.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(events.is_empty(), "hard_case must roll back with the txn");
    }

    /// CC 4.4.3.2.2 rotation-on-removal: removing a member bumps the epoch;
    /// new content seals under a fresh DEK the removed member's keys cannot
    /// unwrap, remaining members can read it, and the PRE-rotation blob is
    /// unchanged (forward-only — the removed member keeps what they had).
    #[tokio::test]
    async fn community_dek_rotation_on_removal_forward_secrecy_sqlite() {
        use crate::federation::community_dek::orchestrate::{
            encrypt_and_cascade_community, read_for_community_viewer,
        };
        use crate::federation::{BlobStorage, FederationDirectory};

        let backend = community_fixture(
            &[("alice", "alice-occ", true), ("bob", "bob-occ", true)],
            None,
        )
        .await;

        // Epoch 0 emission — both members granted + can read.
        let before = encrypt_and_cascade_community(&backend, "comm", b"pre-removal note", None)
            .await
            .unwrap();
        assert_eq!(before.epoch, 0);
        assert_eq!(
            read_for_community_viewer(&backend, &before.at_rest_sha256, "bob-occ")
                .await
                .unwrap(),
            b"pre-removal note"
        );

        // Remove bob — epoch bumps to 1 (rotation-on-removal).
        backend
            .put_community_membership_revocation(comm_revoke("bob", "2026-06-10T00:00:00Z"))
            .await
            .unwrap();
        assert_eq!(
            backend.community_dek_current_epoch("comm").await.unwrap(),
            1
        );

        // New emission seals under epoch 1 — fresh DEK, only alice granted.
        let after = encrypt_and_cascade_community(&backend, "comm", b"post-removal secret", None)
            .await
            .unwrap();
        assert_eq!(after.epoch, 1);
        assert_eq!(after.granted, vec!["alice-occ".to_string()]);
        assert!(!after.granted.contains(&"bob-occ".to_string()));
        assert_ne!(
            before.at_rest_sha256, after.at_rest_sha256,
            "fresh epoch DEK → distinct ciphertext"
        );

        // Remaining member reads the new content; removed member cannot
        // (no grant on epoch 1 — fail-secure, never plaintext).
        assert_eq!(
            read_for_community_viewer(&backend, &after.at_rest_sha256, "alice-occ")
                .await
                .unwrap(),
            b"post-removal secret"
        );
        assert!(matches!(
            read_for_community_viewer(&backend, &after.at_rest_sha256, "bob-occ")
                .await
                .unwrap_err(),
            crate::federation::BlobError::NotGranted { .. }
        ));

        // Forward-only: the PRE-rotation blob is UNCHANGED — bob keeps the
        // grant he already had on epoch 0 and can still read it.
        assert!(backend
            .community_dek_has_member_grant("comm", 0, "bob-occ")
            .await
            .unwrap());
        assert_eq!(
            read_for_community_viewer(&backend, &before.at_rest_sha256, "bob-occ")
                .await
                .unwrap(),
            b"pre-removal note"
        );
    }

    /// v2-ONLY: every community-DEK member grant carries the v2 hybrid
    /// wrap_algorithm; the DB CHECK forbids v1 (CC 4.4.3.4.1 / CC 5.2).
    #[tokio::test]
    async fn community_dek_member_grants_are_v2_only_sqlite() {
        use crate::federation::at_rest_cascade::WRAP_ALGORITHM_V2;
        use crate::federation::community_dek::orchestrate::encrypt_and_cascade_community;

        let backend = community_fixture(&[("alice", "alice-occ", true)], None).await;
        encrypt_and_cascade_community(&backend, "comm", b"x", None)
            .await
            .unwrap();

        // Every member-grant row is v2; a v1 INSERT is rejected by the CHECK.
        let conn = backend.conn.clone();
        let (algs, v1_rejected) = {
            let conn = conn.lock();
            let mut stmt = conn
                .prepare("SELECT wrap_algorithm FROM federation_community_dek_member_grants")
                .unwrap();
            let algs: Vec<String> = stmt
                .query_map([], |r| r.get::<_, String>(0))
                .unwrap()
                .collect::<Result<_, _>>()
                .unwrap();
            let v1_rejected = conn
                .execute(
                    "INSERT INTO federation_community_dek_member_grants \
                     (community_key_id, epoch, member_key_id, wrap_algorithm, wrapped_dek) \
                     VALUES ('comm', 0, 'mallory', 'v1', 'x')",
                    [],
                )
                .is_err();
            (algs, v1_rejected)
        };
        assert!(!algs.is_empty());
        assert!(algs.iter().all(|a| a == WRAP_ALGORITHM_V2));
        assert!(v1_rejected, "the wrap_algorithm CHECK must reject v1");
    }

    // ── v6.1.0 (CIRISPersist#161 Ask 2/4) membership-change re-key ─────

    /// A fresh keyed EncryptionPubkeys pair for a test occurrence (a fresh
    /// x25519 + ML-KEM-768 keypair — only the pubkeys are needed to wrap).
    fn keyed_enc(x_seed: u8) -> crate::federation::EncryptionPubkeys {
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        let x_pub = ciris_crypto::x25519::public_from_secret(&[x_seed; 32]);
        let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
        crate::federation::EncryptionPubkeys {
            x25519_base64: B64.encode(x_pub),
            ml_kem_768_base64: B64.encode(&ml_pub),
        }
    }

    // #418 — returns a bare IdentityOccurrence for the trusted-LOCAL put path
    // (storage tests; the signed gate is exercised by the dedicated adversarial
    // tests). Callers use `put_identity_occurrence_local`.
    fn occ_signed(
        identity: &str,
        occ_key: &str,
        enc: Option<crate::federation::EncryptionPubkeys>,
    ) -> crate::federation::IdentityOccurrence {
        crate::federation::IdentityOccurrence {
            identity_key_id: identity.into(),
            occurrence_key_id: occ_key.into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: "2026-06-10T00:00:00Z".parse().unwrap(),
            valid_until: None,
            encryption_pubkeys: enc,
            transport_binding: None,
            persist_row_hash: String::new(),
        }
    }

    /// v14.0.0 (CIRISPersist#418) — the ADVERSARIAL gate test. Proves
    /// `put_identity_occurrence` (the wire/HTTP path) cryptographically admits a
    /// genuinely-signed occurrence and REJECTS every forgery, closing the
    /// content-MITM where a peer fabricates a victim's KEX keys.
    #[tokio::test]
    async fn signed_identity_occurrence_gate_admits_valid_rejects_forged() {
        use crate::federation::FederationDirectory;
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use ciris_crypto::{Ed25519Signer, MlDsa65Signer};
        use ciris_verify_core::self_at_login::HybridSigningIdentity;
        use ciris_verify_core::transport_binding::{
            compute_destination_hash, produce_signed_identity_occurrence,
        };

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // The identity signs its own occurrence (attesting_key_id == identity →
        // signer_acts_for trivially true). Box the ML-DSA signer (large key) and
        // build BEFORE any await (2 MB test-stack discipline).
        let signer = Box::new(HybridSigningIdentity::new(
            "alice",
            Ed25519Signer::random().unwrap(),
            MlDsa65Signer::new().unwrap(),
        ));
        let member = signer.directory_member().unwrap();

        // Register "alice" in federation_keys with the SIGNER's real pubkeys so
        // the gate resolves them; register the occurrence key too (FK).
        let mut alice = fed_key("alice", "alice", "alice");
        alice.pubkey_ed25519_base64 = member.ed25519_public_key_base64.clone();
        alice.pubkey_ml_dsa_65_base64 = member.mldsa65_public_key_base64.clone();
        backend
            .put_public_key(SignedKeyRecord { record: alice })
            .await
            .unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("alice-phone", "alice", "alice-phone"),
            })
            .await
            .unwrap();

        // Transport + content keys: transport-x ≠ content-KEM-x (§5.6.8.8.2 C4);
        // a derivation-consistent RNS destination_hash.
        let transport_ed = [0x01u8; 32];
        let transport_x = [0x02u8; 32];
        let content_x = [0x03u8; 32];
        let app = "ciris.federation";
        let aspects = vec!["announce".to_string(), "v1".to_string()];
        let dest_hash =
            compute_destination_hash(app, &aspects, &transport_x, &transport_ed).unwrap();
        let tb_env = serde_json::json!({
            "reticulum_x25519_pubkey": B64.encode(transport_x),
            "reticulum_ed25519_pubkey": B64.encode(transport_ed),
            "destination_hash": B64.encode(dest_hash),
            "app_name": app,
            "aspects": aspects,
        });
        let enc_env = serde_json::json!({
            "x25519_base64": B64.encode(content_x),
            "ml_kem_768_base64": B64.encode(vec![0x11u8; 1184]),
        });
        let envelope = serde_json::json!({
            "identity_key_id": "alice",
            "occurrence_key_id": "alice-phone",
            "transport_destination": tb_env,
            "encryption_pubkeys": enc_env,
            "asserted_at": "2026-06-14T00:00:00.000Z",
        });
        let (signed_envelope, signature) =
            produce_signed_identity_occurrence(signer.as_ref(), envelope)
                .await
                .unwrap();

        // Persist's typed projection, matching the signed envelope.
        let typed = |enc_x: &[u8]| crate::federation::IdentityOccurrence {
            identity_key_id: "alice".into(),
            occurrence_key_id: "alice-phone".into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: "2026-06-14T00:00:00Z".parse().unwrap(),
            valid_until: None,
            encryption_pubkeys: Some(crate::federation::EncryptionPubkeys {
                x25519_base64: B64.encode(enc_x),
                ml_kem_768_base64: B64.encode(vec![0x11u8; 1184]),
            }),
            transport_binding: Some(crate::federation::types::OccurrenceTransportBinding {
                reticulum_x25519_pubkey_base64: B64.encode(transport_x),
                reticulum_ed25519_pubkey_base64: B64.encode(transport_ed),
                destination_hash_base64: B64.encode(dest_hash),
                app_name: app.into(),
                aspects: aspects.clone(),
            }),
            persist_row_hash: String::new(),
        };
        let signed = |occ, sig| crate::federation::SignedIdentityOccurrence {
            identity_occurrence: occ,
            attesting_key_id: "alice".to_string(),
            signed_envelope: signed_envelope.clone(),
            signature: sig,
        };

        // (1) VALID → admitted.
        backend
            .put_identity_occurrence(signed(typed(&content_x), signature.clone()))
            .await
            .expect("a genuinely-signed occurrence must be admitted");
        assert!(backend
            .resolve_encryption_keys("alice-phone")
            .await
            .unwrap()
            .is_some());
        // #446 — the ACCEPTED signed occurrence's binding is PROJECTED into
        // the transport_destinations read model (local derived row: visible
        // to the plain read, absent from the signed replication read).
        let routes = backend
            .list_transport_destinations_for("alice-phone")
            .await
            .unwrap();
        assert_eq!(routes.len(), 1, "#446: binding must be materialized");
        // v21.3.0 (CIRISPersist#512) — the projected `destination` is the
        // column's ONE canonical encoding: lowercase HEX of the raw dest
        // hash, exactly the #393 item-2 gate's probe (`hex::encode`). This
        // assertion previously pinned `B64.encode(dest_hash)` — enshrining
        // the encoding split instead of catching it.
        assert_eq!(routes[0].destination, hex::encode(dest_hash));
        assert_eq!(
            routes[0].binding_provenance,
            crate::federation::self_at_login::BindingProvenance::Rooted
        );
        assert_eq!(routes[0].epoch, 0);
        assert!(
            backend
                .list_signed_transport_destinations_for("alice-phone")
                .await
                .unwrap()
                .is_empty(),
            "#446: the projected route must not replicate on the route plane"
        );

        // (2) DIVERGENT typed projection (envelope says content_x, typed claims
        // attacker_x) → REJECTED (the MITM: sig covers only the envelope).
        let err = backend
            .put_identity_occurrence(signed(typed(&[0x44u8; 32]), signature.clone()))
            .await
            .expect_err("a typed projection diverging from the signed envelope must be rejected");
        assert!(format!("{err}").contains("diverges"), "got {err}");

        // (3) FORGED signature → REJECTED.
        let mut bad_sig = signature.clone();
        bad_sig.ed25519_signature_base64 = B64.encode([0u8; 64]);
        let err = backend
            .put_identity_occurrence(signed(typed(&content_x), bad_sig))
            .await
            .expect_err("a forged signature must be rejected");
        assert_eq!(err.kind(), "federation_signature_invalid");

        // (4) WRONG signer (not the identity, not an active occurrence of it) →
        // REJECTED by signer_acts_for.
        let mut wrong = signed(typed(&content_x), signature.clone());
        wrong.attesting_key_id = "alice-phone".to_string(); // registered, but not alice's identity key nor an occurrence
        let err = backend.put_identity_occurrence(wrong).await.expect_err(
            "a signer who is neither the identity nor its active occurrence must be rejected",
        );
        assert_eq!(err.kind(), "federation_signature_invalid");
    }

    /// v14.0.0 (CIRISPersist#418 ask 3) — `resolve_encryption_keys` (the SEALING
    /// lookup) must fail-CLOSED on an admitted revocation. Before this it filtered
    /// only on `valid_until`, so content sealed to a REVOKED KEX key (fail-open).
    #[tokio::test]
    async fn resolve_encryption_keys_excludes_revoked_occurrence() {
        use crate::federation::FederationDirectory;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["root", "phone"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, "root", k),
                })
                .await
                .unwrap();
        }
        // A content-only occurrence with KEX keys (trusted-local path).
        backend
            .put_identity_occurrence_local(occ_signed("root", "phone", Some(keyed_enc(0x33))))
            .await
            .unwrap();
        assert!(
            backend
                .resolve_encryption_keys("phone")
                .await
                .unwrap()
                .is_some(),
            "an un-revoked occurrence resolves its KEX key"
        );

        // Revoke it — effective in the past but AFTER the occurrence's
        // asserted_at (2026-06-10), so it kills the CURRENT binding (#421:
        // the comparator is `effective_at >= asserted_at`).
        backend
            .put_identity_occurrence_revocation_local(
                crate::federation::IdentityOccurrenceRevocation {
                    identity_key_id: "root".into(),
                    occurrence_key_id: "phone".into(),
                    revoked_at: "2026-06-12T00:00:00Z".parse().unwrap(),
                    effective_at: "2026-06-12T00:00:00Z".parse().unwrap(),
                    reason: Some("compromised".into()),
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            )
            .await
            .unwrap();

        assert!(
            backend
                .resolve_encryption_keys("phone")
                .await
                .unwrap()
                .is_none(),
            "a REVOKED occurrence must NOT resolve its KEX key (fail-closed seal)"
        );

        // v16.0.0 (#421) RE-ESTABLISH: a FRESH occurrence under the SAME
        // key_id with asserted_at strictly after the revocation's effective_at
        // (last-signed-wins supersedes the row) recovers sealability —
        // compromise → revoke → re-key → publish → recovered.
        let mut fresh = occ_signed("root", "phone", Some(keyed_enc(0x44)));
        fresh.asserted_at = "2026-06-14T00:00:00Z".parse().unwrap();
        backend.put_identity_occurrence_local(fresh).await.unwrap();
        assert!(
            backend
                .resolve_encryption_keys("phone")
                .await
                .unwrap()
                .is_some(),
            "a fresh occurrence (asserted after the revocation) RE-ESTABLISHES"
        );

        // A replayed OLD revocation (effective before the fresh assertion) is
        // a no-op — it cannot re-brick the re-established binding. (The
        // append-only table keeps the old row; the fold ignores it.)
        assert!(
            backend
                .resolve_encryption_keys("phone")
                .await
                .unwrap()
                .is_some(),
            "the stale revocation row does not out-run the fresh occurrence"
        );
    }

    /// v16.0.0 (CIRISPersist#421) — the FULL LIFECYCLE with the revocation
    /// plane under the REAL signature gate: publish → rotate → revoke →
    /// re-establish, every transition asserted, plus the adversarial forgeries
    /// (garbage sig / unrelated-but-registered signer / divergent typed
    /// projection) each REJECTED with sealability unharmed. The occurrence
    /// writes ride the trusted-local path (the occurrence gate has its own
    /// #418 adversarial test); the REVOCATION writes go through
    /// `put_identity_occurrence_revocation`'s gate with real hybrid crypto.
    #[tokio::test]
    async fn signed_revocation_full_lifecycle_and_forgeries() {
        use crate::federation::FederationDirectory;
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use ciris_crypto::{Ed25519Signer, MlDsa65Signer};
        use ciris_verify_core::self_at_login::HybridSigningIdentity;
        use ciris_verify_core::transport_binding::produce_signed_identity_occurrence;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // alice signs her own revocations; mallory is a REGISTERED but
        // unrelated peer (the "any consented peer" of the attack).
        let alice = Box::new(HybridSigningIdentity::new(
            "alice",
            Ed25519Signer::random().unwrap(),
            MlDsa65Signer::new().unwrap(),
        ));
        let mallory = Box::new(HybridSigningIdentity::new(
            "mallory",
            Ed25519Signer::random().unwrap(),
            MlDsa65Signer::new().unwrap(),
        ));
        let a_member = alice.directory_member().unwrap();
        let m_member = mallory.directory_member().unwrap();
        let mut a_rec = fed_key("alice", "alice", "alice");
        a_rec.pubkey_ed25519_base64 = a_member.ed25519_public_key_base64.clone();
        a_rec.pubkey_ml_dsa_65_base64 = a_member.mldsa65_public_key_base64.clone();
        let mut m_rec = fed_key("mallory", "mallory", "mallory");
        m_rec.pubkey_ed25519_base64 = m_member.ed25519_public_key_base64.clone();
        m_rec.pubkey_ml_dsa_65_base64 = m_member.mldsa65_public_key_base64.clone();
        for rec in [a_rec, m_rec] {
            backend
                .put_public_key(SignedKeyRecord { record: rec })
                .await
                .unwrap();
        }
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("alice-phone", "alice", "alice-phone"),
            })
            .await
            .unwrap();

        let occ_at = |ts: &str, seed: u8| {
            let mut o = occ_signed("alice", "alice-phone", Some(keyed_enc(seed)));
            o.asserted_at = ts.parse().unwrap();
            o
        };
        // (1) PUBLISH — resolvable.
        backend
            .put_identity_occurrence_local(occ_at("2026-06-14T00:00:00Z", 0x11))
            .await
            .unwrap();
        assert!(backend
            .resolve_encryption_keys("alice-phone")
            .await
            .unwrap()
            .is_some());

        // (2) ROTATE — a newer occurrence supersedes; still resolvable.
        backend
            .put_identity_occurrence_local(occ_at("2026-06-16T00:00:00Z", 0x22))
            .await
            .unwrap();
        assert!(backend
            .resolve_encryption_keys("alice-phone")
            .await
            .unwrap()
            .is_some());

        // The revocation envelope alice will sign (effective AFTER the rotate).
        let rev_env = serde_json::json!({
            "identity_key_id": "alice",
            "occurrence_key_id": "alice-phone",
            "revoked_at": "2026-06-18T00:00:00Z",
            "effective_at": "2026-06-18T00:00:00Z",
        });
        let typed_rev = || crate::federation::IdentityOccurrenceRevocation {
            identity_key_id: "alice".into(),
            occurrence_key_id: "alice-phone".into(),
            revoked_at: "2026-06-18T00:00:00Z".parse().unwrap(),
            effective_at: "2026-06-18T00:00:00Z".parse().unwrap(),
            reason: None,
            witness_set: vec![],
            persist_row_hash: String::new(),
        };
        // The producer is envelope-generic (#421 design note): the same
        // `produce_signed_identity_occurrence` signs the revocation envelope.
        let (signed_env, a_sig) =
            produce_signed_identity_occurrence(alice.as_ref(), rev_env.clone())
                .await
                .unwrap();

        // (3a) FORGED signature → REJECTED; sealability unharmed.
        let mut bad_sig = a_sig.clone();
        bad_sig.ed25519_signature_base64 = B64.encode([0u8; 64]);
        let err = backend
            .put_identity_occurrence_revocation(
                crate::federation::SignedIdentityOccurrenceRevocation {
                    identity_occurrence_revocation: typed_rev(),
                    attesting_key_id: "alice".into(),
                    signed_envelope: signed_env.clone(),
                    signature: bad_sig,
                },
            )
            .await
            .expect_err("(3a) a forged revocation signature must be REJECTED");
        assert_eq!(err.kind(), "federation_signature_invalid");
        assert!(backend
            .resolve_encryption_keys("alice-phone")
            .await
            .unwrap()
            .is_some());

        // (3b) UNRELATED-but-REGISTERED signer (mallory validly signs the
        // victim's envelope with her own key) → signer_acts_for REJECTED.
        let (m_env, m_sig) = produce_signed_identity_occurrence(mallory.as_ref(), rev_env.clone())
            .await
            .unwrap();
        let err = backend
            .put_identity_occurrence_revocation(
                crate::federation::SignedIdentityOccurrenceRevocation {
                    identity_occurrence_revocation: typed_rev(),
                    attesting_key_id: "mallory".into(),
                    signed_envelope: m_env,
                    signature: m_sig,
                },
            )
            .await
            .expect_err("(3b) a peer's revocation of a victim must be REJECTED");
        assert_eq!(err.kind(), "federation_signature_invalid");
        assert!(backend
            .resolve_encryption_keys("alice-phone")
            .await
            .unwrap()
            .is_some());

        // (3c) DIVERGENT typed projection (envelope says 06-18, typed claims
        // 06-15 — moving the terminality clock) → REJECTED.
        let mut divergent = typed_rev();
        divergent.effective_at = "2026-06-15T00:00:00Z".parse().unwrap();
        let err = backend
            .put_identity_occurrence_revocation(
                crate::federation::SignedIdentityOccurrenceRevocation {
                    identity_occurrence_revocation: divergent,
                    attesting_key_id: "alice".into(),
                    signed_envelope: signed_env.clone(),
                    signature: a_sig.clone(),
                },
            )
            .await
            .expect_err("(3c) a typed projection diverging from the envelope must be REJECTED");
        assert!(format!("{err}").contains("diverges"), "got {err}");

        // (4) GENUINE signed self-revocation → admitted; sealability killed;
        //     the signed read returns the container byte-exact.
        backend
            .put_identity_occurrence_revocation(
                crate::federation::SignedIdentityOccurrenceRevocation {
                    identity_occurrence_revocation: typed_rev(),
                    attesting_key_id: "alice".into(),
                    signed_envelope: signed_env.clone(),
                    signature: a_sig.clone(),
                },
            )
            .await
            .expect("(4) a genuinely-signed self-revocation must be admitted");
        assert!(
            backend
                .resolve_encryption_keys("alice-phone")
                .await
                .unwrap()
                .is_none(),
            "(4) revoked ⇒ not sealable"
        );
        let signed_revs = backend
            .list_signed_identity_occurrence_revocations_for("alice")
            .await
            .unwrap();
        assert_eq!(
            signed_revs.len(),
            1,
            "(4) signed read returns the container"
        );
        assert_eq!(signed_revs[0].signed_envelope, signed_env);
        assert_eq!(
            signed_revs[0].signature.ed25519_signature_base64,
            a_sig.ed25519_signature_base64
        );

        // (5) RE-ESTABLISH — a fresh occurrence asserted AFTER the revocation
        //     recovers sealability under the same key_id.
        backend
            .put_identity_occurrence_local(occ_at("2026-06-20T00:00:00Z", 0x33))
            .await
            .unwrap();
        assert!(
            backend
                .resolve_encryption_keys("alice-phone")
                .await
                .unwrap()
                .is_some(),
            "(5) a fresh occurrence re-establishes after the revoke"
        );
        // (The stale-occurrence / replayed-old-revocation no-ops are covered in
        // `resolve_encryption_keys_excludes_revoked_occurrence` — the fold
        // comparator test; the GATED occurrence path additionally refuses the
        // downgrade via last-signed-wins, per the #418 adversarial test.)
    }

    /// v14.1.0 (CIRISPersist#418 replication read) — the load-bearing property
    /// for CIRISEdge#305: `list_signed_identity_occurrences_for` reconstructs
    /// the signature container BYTE-EXACT, so re-`put`ting the read row on a
    /// FRESH backend passes the same signature gate (edge can re-publish an
    /// occurrence it cannot re-sign). Trusted-local rows are OMITTED.
    #[tokio::test]
    async fn list_signed_occurrences_roundtrips_through_the_put_gate() {
        use crate::federation::FederationDirectory;
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use ciris_crypto::{Ed25519Signer, MlDsa65Signer};
        use ciris_verify_core::self_at_login::HybridSigningIdentity;
        use ciris_verify_core::transport_binding::{
            compute_destination_hash, produce_signed_identity_occurrence,
        };

        // A backend factory: fresh, migrated, with alice + occurrence keys
        // registered to the SIGNER's real pubkeys (so the gate resolves them).
        async fn seeded(member: &ciris_verify_core::ThresholdMember) -> SqliteBackend {
            let backend = SqliteBackend::open_in_memory().await.unwrap();
            backend.run_migrations().await.unwrap();
            let mut alice = fed_key("alice", "alice", "alice");
            alice.pubkey_ed25519_base64 = member.ed25519_public_key_base64.clone();
            alice.pubkey_ml_dsa_65_base64 = member.mldsa65_public_key_base64.clone();
            backend
                .put_public_key(SignedKeyRecord { record: alice })
                .await
                .unwrap();
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key("alice-phone", "alice", "alice-phone"),
                })
                .await
                .unwrap();
            // A content-only trusted-local occurrence — MUST be omitted from
            // list_signed (it was never signed-put).
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key("alice-laptop", "alice", "alice-laptop"),
                })
                .await
                .unwrap();
            backend
                .put_identity_occurrence_local(occ_signed(
                    "alice",
                    "alice-laptop",
                    Some(keyed_enc(0x55)),
                ))
                .await
                .unwrap();
            backend
        }

        let signer = Box::new(HybridSigningIdentity::new(
            "alice",
            Ed25519Signer::random().unwrap(),
            MlDsa65Signer::new().unwrap(),
        ));
        let member = signer.directory_member().unwrap();

        let transport_ed = [0x01u8; 32];
        let transport_x = [0x02u8; 32];
        let content_x = [0x03u8; 32];
        let app = "ciris.federation";
        let aspects = vec!["announce".to_string(), "v1".to_string()];
        let dest_hash =
            compute_destination_hash(app, &aspects, &transport_x, &transport_ed).unwrap();
        let envelope = serde_json::json!({
            "identity_key_id": "alice",
            "occurrence_key_id": "alice-phone",
            "transport_destination": {
                "reticulum_x25519_pubkey": B64.encode(transport_x),
                "reticulum_ed25519_pubkey": B64.encode(transport_ed),
                "destination_hash": B64.encode(dest_hash),
                "app_name": app,
                "aspects": aspects,
            },
            "encryption_pubkeys": {
                "x25519_base64": B64.encode(content_x),
                "ml_kem_768_base64": B64.encode(vec![0x11u8; 1184]),
            },
            "asserted_at": "2026-06-14T00:00:00.000Z",
        });
        let (signed_envelope, signature) =
            produce_signed_identity_occurrence(signer.as_ref(), envelope)
                .await
                .unwrap();
        let signed = crate::federation::SignedIdentityOccurrence {
            identity_occurrence: crate::federation::IdentityOccurrence {
                identity_key_id: "alice".into(),
                occurrence_key_id: "alice-phone".into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: "2026-06-14T00:00:00Z".parse().unwrap(),
                valid_until: None,
                encryption_pubkeys: Some(crate::federation::EncryptionPubkeys {
                    x25519_base64: B64.encode(content_x),
                    ml_kem_768_base64: B64.encode(vec![0x11u8; 1184]),
                }),
                transport_binding: Some(crate::federation::types::OccurrenceTransportBinding {
                    reticulum_x25519_pubkey_base64: B64.encode(transport_x),
                    reticulum_ed25519_pubkey_base64: B64.encode(transport_ed),
                    destination_hash_base64: B64.encode(dest_hash),
                    app_name: app.into(),
                    aspects: aspects.clone(),
                }),
                persist_row_hash: String::new(),
            },
            attesting_key_id: "alice".to_string(),
            signed_envelope: signed_envelope.clone(),
            signature: signature.clone(),
        };

        // Origin backend: signed-put + one trusted-local row.
        let origin = seeded(&member).await;
        origin
            .put_identity_occurrence(signed.clone())
            .await
            .expect("valid signed occurrence admitted");

        // list_signed returns ONLY the signed-put row (the trusted-local
        // alice-laptop occurrence is omitted).
        let read = origin
            .list_signed_identity_occurrences_for("alice")
            .await
            .unwrap();
        assert_eq!(read.len(), 1, "only the signed-put occurrence is listed");
        assert_eq!(read[0].attesting_key_id, "alice");
        assert_eq!(read[0].identity_occurrence.occurrence_key_id, "alice-phone");
        // The signature container round-trips byte-exact.
        assert_eq!(read[0].signed_envelope, signed_envelope);
        assert_eq!(
            read[0].signature.ed25519_signature_base64,
            signature.ed25519_signature_base64
        );

        // The keystone: re-`put` the READ tuple on a fresh peer backend — the
        // gate re-verifies over the reconstructed signed_envelope and admits.
        // (Edge holds no identity key; it can only replay what it read.)
        let peer = seeded(&member).await;
        peer.put_identity_occurrence(read.into_iter().next().unwrap())
            .await
            .expect("a re-published signed occurrence must pass the peer's gate byte-exact");
        assert!(
            peer.resolve_encryption_keys("alice-phone")
                .await
                .unwrap()
                .is_some(),
            "the replicated occurrence resolves its KEX key on the peer"
        );
    }

    /// v16.0.0 (CIRISPersist#425) — the uniform `list_signed_records` dispatch
    /// returns byte-exact records per kind and empties cleanly for kinds with
    /// no rows, so an edge engine can sweep a subject across
    /// `ReplicatedKind::all()` through one call.
    #[tokio::test]
    async fn list_signed_records_dispatches_per_kind() {
        use crate::federation::namespace::ReplicatedKind as K;
        use crate::federation::FederationDirectory;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("node-x", "node-x", "node-x"),
            })
            .await
            .unwrap();

        // KeyRecord kind → the subject's own row, byte-exact (embedded scrub sig).
        let keys = backend
            .list_signed_records(K::KeyRecord, "node-x")
            .await
            .unwrap();
        assert_eq!(keys.len(), 1);
        assert_eq!(keys[0].kind, K::KeyRecord);
        assert_eq!(keys[0].canonical_json["key_id"], "node-x");

        // Kinds with no rows for this subject return empty, not error.
        for k in [
            K::IdentityOccurrence,
            K::TransportDestination,
            K::Attestation,
            K::IdentityOccurrenceRevocation,
        ] {
            assert!(
                backend
                    .list_signed_records(k, "node-x")
                    .await
                    .unwrap()
                    .is_empty(),
                "{k:?} must be empty for a bare subject"
            );
        }

        // An unknown subject is empty across all kinds.
        for k in K::all() {
            assert!(backend
                .list_signed_records(*k, "nobody")
                .await
                .unwrap()
                .is_empty());
        }
    }

    /// The keystone: a newcomer self-occurrence gains access to a
    /// pre-existing self-scope blob via the retroactive ADD re-wrap, and a
    /// re-run is idempotent (adds no further grants).
    #[tokio::test]
    async fn rekey_self_add_newcomer_reads_preexisting_blob_idempotent() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_self_occurrence_add,
        };
        use crate::federation::types::cohort_scope::SELF;
        use crate::federation::FederationDirectory;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["root", "occ-old", "occ-new"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, "root", k),
                })
                .await
                .unwrap();
        }
        // Only the OLD occurrence exists at write time.
        backend
            .put_identity_occurrence_local(occ_signed("root", "occ-old", Some(keyed_enc(0x11))))
            .await
            .unwrap();

        let plaintext = b"a self-scoped note written before the new device joined";
        let result = encrypt_and_cascade(&backend, SELF, "root", plaintext, None)
            .await
            .unwrap();
        assert_eq!(result.granted, vec!["occ-old".to_string()]);

        // The new occurrence joins AFTER the write — initially NO grant.
        backend
            .put_identity_occurrence_local(occ_signed("root", "occ-new", Some(keyed_enc(0x22))))
            .await
            .unwrap();
        assert!(
            read_for_viewer(&backend, &result.at_rest_sha256, "occ-new")
                .await
                .is_err(),
            "newcomer cannot read before the re-key walk"
        );

        // Run the re-key ADD walk for the newcomer.
        let rk = rekey_self_occurrence_add(
            &backend,
            "root",
            &["occ-new".to_string()],
            chrono::Utc::now(),
        )
        .await
        .unwrap();
        assert_eq!(rk.blobs_scanned, 1);
        assert_eq!(rk.granted, vec![("occ-new".to_string(), 1)]);
        assert!(rk.excluded.is_empty());

        // Newcomer now reads the pre-existing blob.
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, "occ-new")
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // Idempotent: a second walk adds zero grants.
        let rk2 = rekey_self_occurrence_add(
            &backend,
            "root",
            &["occ-new".to_string()],
            chrono::Utc::now(),
        )
        .await
        .unwrap();
        assert_eq!(rk2.granted, vec![("occ-new".to_string(), 0)]);
        let recipients = backend
            .list_at_rest_grant_recipients(&result.at_rest_sha256)
            .await
            .unwrap();
        assert_eq!(
            recipients,
            vec!["occ-new".to_string(), "occ-old".to_string()]
        );
    }

    /// A keyless newcomer is fail-secure excluded (no grant on ANY blob)
    /// and surfaced as `hard_case:recipient_excluded` +
    /// `hard_case:family_membership_change`; both are idempotent.
    #[tokio::test]
    async fn rekey_family_add_failsecure_excludes_keyless_and_emits_hard_cases() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::FederationDirectory;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["fam", "alice", "carol", "alice-phone", "carol-phone"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        // The family roster includes alice + carol from the start (V067
        // models removal, not roster mutation; an add is a roster-set + a
        // re-key walk once the newcomer's occurrence/keys arrive). alice
        // has a keyed occurrence and writes a blob; carol's KEYLESS
        // occurrence is registered only afterwards, so the original write
        // could not reach her.
        backend
            .put_identity_occurrence_local(occ_signed(
                "alice",
                "alice-phone",
                Some(keyed_enc(0x33)),
            ))
            .await
            .unwrap();
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "fam",
                fed_family("fam", "Household", vec!["alice", "carol"], "unanimous"),
            ))
            .await
            .unwrap();
        let plaintext = b"family blob written before carol registered a device";
        let result = encrypt_and_cascade(&backend, FAMILY, "fam", plaintext, None)
            .await
            .unwrap();
        assert_eq!(result.granted, vec!["alice-phone".to_string()]);

        // carol registers a KEYLESS occurrence (her wrap target is invalid).
        backend
            .put_identity_occurrence_local(occ_signed("carol", "carol-phone", None))
            .await
            .unwrap();

        let observed = chrono::Utc::now();
        let rk = rekey_family_member_add(&backend, "fam", "carol", observed)
            .await
            .unwrap();
        assert_eq!(rk.blobs_scanned, 1);
        assert!(rk.granted.is_empty(), "keyless newcomer is never granted");
        assert_eq!(rk.excluded, vec!["carol-phone".to_string()]);

        // carol-phone still cannot read (fail-secure: no plaintext fallback).
        assert!(
            read_for_viewer(&backend, &result.at_rest_sha256, "carol-phone")
                .await
                .is_err()
        );

        // hard_case rows: one family_membership_change + one recipient_excluded.
        let mc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::FAMILY_MEMBERSHIP_CHANGE.into()),
                since: None,
            })
            .await
            .unwrap();
        assert_eq!(mc.len(), 1);
        assert_eq!(mc[0].subject_key_id.as_deref(), Some("carol-phone"));
        assert_eq!(mc[0].target_key_id.as_deref(), Some("fam"));

        let exc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
            })
            .await
            .unwrap();
        assert_eq!(exc.len(), 1);
        assert_eq!(exc[0].subject_key_id.as_deref(), Some("carol-phone"));

        // Idempotent emission: re-running at the same instant adds no rows.
        rekey_family_member_add(&backend, "fam", "carol", observed)
            .await
            .unwrap();
        let all = backend
            .list_hard_case_events(HardCaseFilter::default())
            .await
            .unwrap();
        assert_eq!(all.len(), 2, "re-run at same instant is idempotent");
    }

    /// v6.2.0 (#161 A4/A5) — the forward-path half of the keystone: a
    /// genuinely-new family member (NOT on the roster at write time) is
    /// added to the roster by `rekey_family_member_add` and is then served
    /// FUTURE family writes, not just re-keyed onto past blobs. This is the
    /// gap the roster-grow primitive (`add_family_member`) closes.
    #[tokio::test]
    async fn rekey_family_member_add_grows_roster_and_serves_future_writes() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::FederationDirectory;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["fam", "alice", "bob", "alice-phone", "bob-phone"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        backend
            .put_identity_occurrence_local(occ_signed(
                "alice",
                "alice-phone",
                Some(keyed_enc(0x66)),
            ))
            .await
            .unwrap();
        // Roster starts with alice ONLY — bob is a genuinely-new member.
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "fam",
                fed_family("fam", "Household", vec!["alice"], "unanimous"),
            ))
            .await
            .unwrap();

        // A blob written before bob exists reaches only alice.
        let blob1 = encrypt_and_cascade(&backend, FAMILY, "fam", b"before bob", None)
            .await
            .unwrap();
        assert_eq!(blob1.granted, vec!["alice-phone".to_string()]);

        // bob registers a KEYED occurrence, then is admitted.
        backend
            .put_identity_occurrence_local(occ_signed("bob", "bob-phone", Some(keyed_enc(0x77))))
            .await
            .unwrap();
        let rk = rekey_family_member_add(&backend, "fam", "bob", chrono::Utc::now())
            .await
            .unwrap();
        // Backward path: bob-phone gets a grant on the one past blob.
        assert_eq!(rk.granted, vec![("bob-phone".to_string(), 1)]);
        assert!(
            read_for_viewer(&backend, &blob1.at_rest_sha256, "bob-phone")
                .await
                .is_ok()
        );

        // Roster grew: bob is now a member.
        let fam = backend.lookup_family("fam").await.unwrap().unwrap();
        assert!(
            fam.members.iter().any(|m| m.key_id == "bob"),
            "add_family_member put bob on the roster"
        );

        // Forward path (the gap this closes): a NEW write reaches BOTH.
        let blob2 = encrypt_and_cascade(&backend, FAMILY, "fam", b"after bob", None)
            .await
            .unwrap();
        let mut granted = blob2.granted.clone();
        granted.sort();
        assert_eq!(
            granted,
            vec!["alice-phone".to_string(), "bob-phone".to_string()],
            "future family write reaches the newly-admitted member"
        );

        // Idempotent admission: re-adding bob is a no-op, no duplicate row.
        assert!(
            !backend
                .add_family_member(
                    "fam",
                    crate::federation::types::FamilyMember {
                        key_id: "bob".into(),
                        joined_at: chrono::Utc::now(),
                        role: None,
                    },
                )
                .await
                .unwrap(),
            "re-admitting an existing member returns false"
        );
        let fam2 = backend.lookup_family("fam").await.unwrap().unwrap();
        assert_eq!(
            fam2.members.iter().filter(|m| m.key_id == "bob").count(),
            1,
            "no duplicate roster entry"
        );
    }

    /// Producer-side stop-wrapping: a member removed via V067 is dropped
    /// from `*_active`, so a NEW family cascade write excludes them — proven
    /// without any explicit gate (the enumeration already enforces it).
    #[tokio::test]
    async fn removed_member_excluded_from_new_family_write() {
        use crate::federation::at_rest_cascade::orchestrate::encrypt_and_cascade;
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::FederationDirectory;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["fam", "alice", "dave", "alice-phone", "dave-phone"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        backend
            .put_identity_occurrence_local(occ_signed(
                "alice",
                "alice-phone",
                Some(keyed_enc(0x44)),
            ))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(occ_signed("dave", "dave-phone", Some(keyed_enc(0x55))))
            .await
            .unwrap();
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "fam",
                fed_family("fam", "Household", vec!["alice", "dave"], "unanimous"),
            ))
            .await
            .unwrap();

        // Before removal: both occurrences are granted on a write.
        let before = encrypt_and_cascade(&backend, FAMILY, "fam", b"v1", None)
            .await
            .unwrap();
        let mut g = before.granted.clone();
        g.sort();
        assert_eq!(g, vec!["alice-phone".to_string(), "dave-phone".to_string()]);

        // Remove dave (V067 effective immediately).
        backend
            .put_family_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_family_membership_revocation(
                    "fam",
                    crate::federation::FamilyMembershipRevocation {
                        family_key_id: "fam".into(),
                        removed_identity_key_id: "dave".into(),
                        removed_at: "2026-06-11T00:00:00Z".parse().unwrap(),
                        effective_at: "2026-06-11T00:00:00Z".parse().unwrap(),
                        reason: Some("left the household".into()),
                        witness_set: vec![],
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();

        // After removal: a NEW write excludes dave (producer stop-wrapping
        // via the *_active enumeration — forward secrecy under a fresh DEK).
        let after = encrypt_and_cascade(&backend, FAMILY, "fam", b"v2-post-removal", None)
            .await
            .unwrap();
        assert_eq!(after.granted, vec!["alice-phone".to_string()]);
        assert!(
            !after.granted.contains(&"dave-phone".to_string()),
            "removed member must not receive grants on new content"
        );
    }

    /// Round-trip an identity_occurrence: write → list_for → reverse
    /// lookup. Covers the column + serde + index plumbing end-to-end.
    #[tokio::test]
    async fn identity_occurrence_round_trip() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("alice-root", "alice", "alice-root"),
            })
            .await
            .unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("alice-phone", "alice", "alice-root"),
            })
            .await
            .unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("alice-laptop", "alice", "alice-root"),
            })
            .await
            .unwrap();

        backend
            .put_identity_occurrence_local(fed_identity_occurrence(
                "alice-root",
                "alice-phone",
                crate::federation::types::device_class::PHONE,
            ))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(fed_identity_occurrence(
                "alice-root",
                "alice-laptop",
                crate::federation::types::device_class::LAPTOP,
            ))
            .await
            .unwrap();

        let occs = backend
            .list_identity_occurrences_for("alice-root")
            .await
            .unwrap();
        assert_eq!(occs.len(), 2);
        assert_eq!(occs[0].occurrence_key_id, "alice-laptop"); // lex ASC
        assert_eq!(occs[1].occurrence_key_id, "alice-phone");
        for o in &occs {
            assert_eq!(o.identity_key_id, "alice-root");
            assert_eq!(o.persist_row_hash.len(), 64);
        }

        let rev = backend
            .lookup_identity_for_occurrence("alice-phone")
            .await
            .unwrap()
            .expect("alice-phone is bound");
        assert_eq!(rev.identity_key_id, "alice-root");
        assert_eq!(rev.device_class, "phone");

        // Unbound key returns None.
        let none = backend
            .lookup_identity_for_occurrence("not-bound")
            .await
            .unwrap();
        assert!(none.is_none());
    }

    /// v13.5.0 (CIRISPersist#397, V098) — the transport-tier Ed25519 pubkey
    /// round-trips through put/list. An explicit-hash canonical that cannot
    /// announce is primed by a peer reading (dest_hash, transport_ed25519)
    /// off its transport_destination row; without this column the pair was
    /// unreachable. Also proves the column is nullable (non-Reticulum kinds
    /// leave it None) and that a re-assert refreshes it in place.
    #[tokio::test]
    async fn transport_ed25519_pubkey_round_trips() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("canon-1", "canon", "canon-1"),
            })
            .await
            .unwrap();

        let now = chrono::Utc::now();
        let ret = crate::federation::TransportDestination {
            occurrence_key_id: "canon-1".into(),
            transport_kind: "reticulum".into(),
            destination: "deadbeef".into(),
            asserted_at: now,
            last_seen_at: Some(now),
            transport_ed25519_pubkey_base64: Some("dHJhbnNwb3J0LWVkMjU1MTk=".into()),
            transport_x25519_pubkey_base64: Some("dHJhbnNwb3J0LXgyNTUxOQ==".into()),
            binding_provenance: crate::federation::self_at_login::BindingProvenance::Rooted,
            epoch: 0,
            retired_at: None,
        };
        // A non-Reticulum kind carries no RNS transport key → None.
        let ws = crate::federation::TransportDestination {
            occurrence_key_id: "canon-1".into(),
            transport_kind: "websocket".into(),
            destination: "wss://relay.example/x".into(),
            asserted_at: now,
            last_seen_at: Some(now),
            transport_ed25519_pubkey_base64: None,
            transport_x25519_pubkey_base64: None,
            binding_provenance: crate::federation::self_at_login::BindingProvenance::Rooted,
            epoch: 0,
            retired_at: None,
        };
        backend.put_transport_destination(&ret).await.unwrap();
        backend.put_transport_destination(&ws).await.unwrap();

        let rows = backend
            .list_transport_destinations_for("canon-1")
            .await
            .unwrap();
        assert_eq!(rows.len(), 2);
        // ORDER BY transport_kind, destination → reticulum before websocket.
        assert_eq!(rows[0].transport_kind, "reticulum");
        assert_eq!(
            rows[0].transport_ed25519_pubkey_base64.as_deref(),
            Some("dHJhbnNwb3J0LWVkMjU1MTk="),
            "the transport-tier Ed25519 must survive the round-trip"
        );
        assert_eq!(
            rows[0].transport_x25519_pubkey_base64.as_deref(),
            Some("dHJhbnNwb3J0LXgyNTUxOQ=="),
            "the transport-tier X25519 (KEX) must survive the round-trip (#411)"
        );
        assert_eq!(rows[1].transport_kind, "websocket");
        assert_eq!(
            rows[1].transport_ed25519_pubkey_base64, None,
            "non-Reticulum kinds carry no RNS transport key"
        );

        // A re-assert with a rotated transport key refreshes it in place —
        // #443: the re-assert must be NEWER (the monotonic guard drops a
        // same-clock replay; a genuine rotation always carries a fresh
        // asserted_at).
        let rotated = crate::federation::TransportDestination {
            transport_ed25519_pubkey_base64: Some("cm90YXRlZC1lZDI1NTE5".into()),
            asserted_at: now + chrono::Duration::seconds(1),
            ..ret.clone()
        };
        backend.put_transport_destination(&rotated).await.unwrap();
        let rows = backend
            .list_transport_destinations_for("canon-1")
            .await
            .unwrap();
        assert_eq!(rows.len(), 2, "re-assert on the PK does not add a row");
        assert_eq!(
            rows[0].transport_ed25519_pubkey_base64.as_deref(),
            Some("cm90YXRlZC1lZDI1NTE5"),
            "re-assert refreshes the transport key in place"
        );
    }

    /// v13.8.0 (CIRISPersist#411) — the BOOT RELOAD: `list_all_transport_destinations`
    /// returns every rooted binding across ALL occurrences (the per-key variant
    /// can't reconstruct the whole set), with the transport-tier X25519 (KEX)
    /// intact — so replication can re-seal envelopes after a restart without a
    /// re-announce. Persist is the source of truth for rooted-peer transport state.
    #[tokio::test]
    async fn list_all_transport_destinations_reloads_every_binding_with_x25519() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for kid in ["node-a", "node-b"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(kid, kid, kid),
                })
                .await
                .unwrap();
        }
        let now = chrono::Utc::now();
        let td = |occ: &str, dest: &str, x: &str| crate::federation::TransportDestination {
            occurrence_key_id: occ.into(),
            transport_kind: "reticulum".into(),
            destination: dest.into(),
            asserted_at: now,
            last_seen_at: Some(now),
            transport_ed25519_pubkey_base64: Some("ZWQ=".into()),
            transport_x25519_pubkey_base64: Some(x.into()),
            binding_provenance: crate::federation::self_at_login::BindingProvenance::Rooted,
            epoch: 0,
            retired_at: None,
        };
        backend
            .put_transport_destination(&td("node-a", "aaaa", "eDI1NTE5LWE="))
            .await
            .unwrap();
        backend
            .put_transport_destination(&td("node-b", "bbbb", "eDI1NTE5LWI="))
            .await
            .unwrap();

        // Per-key sees only its own; list-ALL is the boot reload of every binding.
        assert_eq!(
            backend
                .list_transport_destinations_for("node-a")
                .await
                .unwrap()
                .len(),
            1
        );
        let all = backend.list_all_transport_destinations().await.unwrap();
        assert_eq!(all.len(), 2, "boot reload returns every rooted binding");
        // ORDER BY occurrence_key_id → node-a before node-b.
        assert_eq!(all[0].occurrence_key_id, "node-a");
        assert_eq!(
            all[0].transport_x25519_pubkey_base64.as_deref(),
            Some("eDI1NTE5LWE="),
            "the transport-tier X25519 (KEX) survives — replication can re-seal after restart"
        );
        assert_eq!(all[1].occurrence_key_id, "node-b");
        assert_eq!(
            all[1].transport_x25519_pubkey_base64.as_deref(),
            Some("eDI1NTE5LWI=")
        );
    }

    /// v13.9.0 (CIRISPersist#413, CC 3.3.6.2) — the AV-42 spoof is admitted, not
    /// rejected: two different keys claiming the SAME dest-hash BOTH persist as
    /// distinct rows (competing claims), each carrying its `binding_provenance`,
    /// and `list_transport_destinations_by_destination` surfaces both so routing
    /// can PREFER the `rooted` claim over the `advisory` spoof. The tag also
    /// survives the boot-load (`list_all`) read.
    #[tokio::test]
    async fn competing_claims_admitted_with_provenance_and_surfaced() {
        use crate::federation::self_at_login::BindingProvenance;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for kid in ["real-canon", "spoofer"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(kid, kid, kid),
                })
                .await
                .unwrap();
        }
        let now = chrono::Utc::now();
        let td = |occ: &str, prov: BindingProvenance| crate::federation::TransportDestination {
            occurrence_key_id: occ.into(),
            transport_kind: "reticulum".into(),
            destination: "same-dest-hash".into(), // BOTH claim the same dest-hash
            asserted_at: now,
            last_seen_at: Some(now),
            transport_ed25519_pubkey_base64: None,
            transport_x25519_pubkey_base64: None,
            binding_provenance: prov,
            epoch: 0,
            retired_at: None,
        };
        // The real canonical roots it; an adversary announces the SAME dest-hash
        // under its own key (advisory) — the classic AV-42 spoof.
        backend
            .put_transport_destination(&td("real-canon", BindingProvenance::Rooted))
            .await
            .unwrap();
        backend
            .put_transport_destination(&td("spoofer", BindingProvenance::Advisory))
            .await
            .unwrap();

        // BOTH admitted — the substrate never rejects a competing claim.
        let claimants = backend
            .list_transport_destinations_by_destination("same-dest-hash")
            .await
            .unwrap();
        assert_eq!(claimants.len(), 2, "competing claims must BOTH be admitted");
        let rooted: Vec<_> = claimants
            .iter()
            .filter(|c| c.binding_provenance == BindingProvenance::Rooted)
            .collect();
        let advisory: Vec<_> = claimants
            .iter()
            .filter(|c| c.binding_provenance == BindingProvenance::Advisory)
            .collect();
        assert_eq!(rooted.len(), 1, "one rooted claim");
        assert_eq!(rooted[0].occurrence_key_id, "real-canon");
        assert_eq!(advisory.len(), 1, "one advisory (spoof) claim");
        assert_eq!(advisory[0].occurrence_key_id, "spoofer");

        // The provenance tag survives the boot-load read too.
        let all = backend.list_all_transport_destinations().await.unwrap();
        assert!(all.iter().any(|d| d.occurrence_key_id == "real-canon"
            && d.binding_provenance == BindingProvenance::Rooted));
        assert!(all.iter().any(|d| d.occurrence_key_id == "spoofer"
            && d.binding_provenance == BindingProvenance::Advisory));
    }

    /// v13.9.1 (CIRISPersist#416) — an ADVISORY binding names a not-yet-rooted
    /// key that is NOT in `federation_keys` (admit-advisory, CC 3.3.6.2). The
    /// V078 FK rejected exactly this row; V101 dropped it. Proves the durable
    /// write-through now succeeds for an unrooted key AND the KEX persists +
    /// boot-loads (`resolve_peer_kex_pubkeys` will read it after a restart).
    #[tokio::test]
    async fn advisory_binding_for_unrooted_key_persists_without_fk() {
        use crate::federation::self_at_login::BindingProvenance;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // "unrooted-peer" is deliberately NOT registered in federation_keys.
        let now = chrono::Utc::now();
        backend
            .put_transport_destination(&crate::federation::TransportDestination {
                occurrence_key_id: "unrooted-peer".into(),
                transport_kind: "reticulum".into(),
                destination: "deadbeef".into(),
                asserted_at: now,
                last_seen_at: Some(now),
                transport_ed25519_pubkey_base64: Some("ZWQ=".into()),
                transport_x25519_pubkey_base64: Some("eDI1".into()),
                binding_provenance: BindingProvenance::Advisory,
                epoch: 0,
                retired_at: None,
            })
            .await
            .expect("advisory binding for a not-yet-rooted key MUST persist (#416: FK dropped)");

        // Durable: it reads back (survives a restart / boot-load), KEX intact.
        let rows = backend.list_all_transport_destinations().await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].occurrence_key_id, "unrooted-peer");
        assert_eq!(rows[0].binding_provenance, BindingProvenance::Advisory);
        assert_eq!(
            rows[0].transport_x25519_pubkey_base64.as_deref(),
            Some("eDI1"),
            "the KEX half persists for the durable resolve after restart"
        );
    }

    /// v4.0 (CIRISPersist#160, V060, FSD §4.3) — cohort_scope +
    /// cohort_target_id round-trip through the real SQLite trace_events
    /// store: a community-scoped row with a target inserts and reads
    /// back with both columns intact (proves the INSERT + SELECT column
    /// wiring on the SQLite backend).
    #[tokio::test]
    async fn trace_events_cohort_scope_round_trips_sqlite() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        let mut row = fixture_event_row("trace-cohort-sqlite", 0);
        row.cohort_scope = "community".to_owned();
        row.cohort_target_id = Some("community-key:lens-beta".to_owned());
        backend
            .insert_trace_events_batch(std::slice::from_ref(&row))
            .await
            .unwrap();

        let page = backend.fetch_trace_events_page(0, 10, None).await.unwrap();
        assert_eq!(page.len(), 1);
        let (_id, got) = &page[0];
        assert_eq!(got.cohort_scope, "community");
        assert_eq!(
            got.cohort_target_id.as_deref(),
            Some("community-key:lens-beta")
        );

        // A default-federation row reads back as 'federation' / NULL
        // (backward-compat column DEFAULT honored).
        let fed = fixture_event_row("trace-cohort-fed", 1);
        backend
            .insert_trace_events_batch(std::slice::from_ref(&fed))
            .await
            .unwrap();
        let page2 = backend
            .fetch_trace_events_page(0, 10, Some("deadbeef"))
            .await
            .unwrap();
        let fed_row = page2
            .iter()
            .find(|(_, r)| r.trace_id == "trace-cohort-fed")
            .map(|(_, r)| r)
            .unwrap();
        assert_eq!(fed_row.cohort_scope, "federation");
        assert_eq!(fed_row.cohort_target_id, None);
    }

