    // ── Cut #171 phase 1: local-tier write (upsert/insert + gates) ──

    fn local_input(
        attesting: &str,
        attestation_type: &str,
        dimension: &str,
        subjects: Vec<String>,
    ) -> crate::federation::types::LocalAttestationInput {
        crate::federation::types::LocalAttestationInput {
            attestation_id: None,
            attesting_key_id: attesting.into(),
            attested_key_id: None,
            attestation_type: attestation_type.into(),
            weight: Some(1.0),
            expires_at: None,
            attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({
                    "id": "x", "dimension": dimension, "score": 1.0, "confidence": 0.9,
                }),
            )
            .unwrap(),
            subject_key_ids: subjects,
            cohort_scope: crate::federation::types::cohort_scope::SELF.to_string(),
            scrub_signature_classical: None,
            scrub_signature_pqc: None,
        }
    }

    async fn fresh_backend_with_occurrence(occ: &str) -> SqliteBackend {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key_with_identity_type(
                    occ,
                    "registry",
                    occ,
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();
        backend
    }

    use crate::federation::types::attestation_type::{SCORES, WITHDRAWS};

    /// Read local rows directly (the FederationDirectory trust-reads now
    /// exclude tier='local' — AV-59 — so tests count via the DB).
    /// Returns (tier, scrub_signature_classical) per local row.
    fn local_rows(backend: &SqliteBackend, attesting: &str) -> Vec<(String, String)> {
        let conn = backend.conn_handle();
        let conn = conn.lock();
        let mut stmt = conn
            .prepare(
                "SELECT tier, scrub_signature_classical FROM federation_attestations \
                 WHERE attesting_key_id = ?1 AND tier = 'local'",
            )
            .unwrap();
        stmt.query_map([attesting], |r| {
            Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?))
        })
        .unwrap()
        .collect::<Result<Vec<_>, _>>()
        .unwrap()
    }

    /// v5.0.0 (CIRISPersist#171) — the batched bulk-insert the agent's
    /// boot-time `migrate_graph_nodes_to_attestations()` calls. Returns
    /// one id per input in order; `upsert_many` collapses same-dimension
    /// inputs on `(occurrence, dimension)` while `insert_many` appends a
    /// distinct row per input (multi-valued dimensions).
    #[tokio::test]
    async fn sqlite_local_write_many_batches() {
        let backend = fresh_backend_with_occurrence("occ").await;

        // upsert_many over 3 inputs spanning 2 dimensions → 3 ids back, but
        // the two `identity_binding:v1` rows collapse to ONE row (upsert).
        let ids = backend
            .attestation_upsert_local_many(vec![
                local_input("occ", SCORES, "identity_binding:v1", vec![]),
                local_input("occ", SCORES, "capability:reasoning:v1", vec![]),
                local_input("occ", SCORES, "identity_binding:v1", vec![]),
            ])
            .await
            .unwrap();
        assert_eq!(ids.len(), 3, "one id per input, in order");
        let upsert_rows = local_rows(&backend, "occ");
        assert_eq!(
            upsert_rows.len(),
            2,
            "upsert_many collapses the duplicate dimension to one row"
        );

        // insert_many appends a fresh row per input even on a repeated
        // dimension (multi-valued / event shape — memory, verdicts).
        let ins_ids = backend
            .attestation_insert_local_many(vec![
                local_input("occ", SCORES, "capability:reasoning:v1", vec![]),
                local_input("occ", SCORES, "capability:reasoning:v1", vec![]),
            ])
            .await
            .unwrap();
        assert_eq!(ins_ids.len(), 2);
        assert_eq!(
            local_rows(&backend, "occ").len(),
            4,
            "insert_many appends 2 distinct rows (no collapse) on top of the 2 upsert rows"
        );
    }

    #[tokio::test]
    async fn sqlite_local_upsert_replaces_on_dimension() {
        let backend = fresh_backend_with_occurrence("occ").await;
        // Two upserts of the same dimension → exactly one local row (replace).
        backend
            .attestation_upsert_local(local_input("occ", SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        backend
            .attestation_upsert_local(local_input("occ", SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        let local = local_rows(&backend, "occ");
        assert_eq!(local.len(), 1, "upsert replaces on (occurrence, dimension)");
        assert_eq!(local[0].0, "local");
        assert!(
            local[0].1.is_empty(),
            "local row carries the deferred empty-sentinel signature"
        );
        // AV-59: the FederationDirectory trust-read does NOT surface local.
        let trust = crate::federation::FederationDirectory::list_attestations_for(&backend, "occ")
            .await
            .unwrap();
        assert!(
            trust.is_empty(),
            "local rows must not leak through the federation trust-read (AV-59)"
        );
    }

    #[tokio::test]
    async fn sqlite_local_insert_appends_multivalued() {
        let backend = fresh_backend_with_occurrence("occ").await;
        let id1 = backend
            .attestation_insert_local(local_input("occ", SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        let id2 = backend
            .attestation_insert_local(local_input("occ", SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        assert_ne!(id1, id2, "append yields distinct ids");
        assert_eq!(
            local_rows(&backend, "occ").len(),
            2,
            "insert appends, never collapses by dimension"
        );
    }

    #[tokio::test]
    async fn sqlite_local_rejects_capacity_self_emission() {
        let backend = fresh_backend_with_occurrence("occ").await;
        // capacity:* is the §7.5 anti-Goodhart bypass — ineligible for local.
        let err = backend
            .attestation_upsert_local(local_input(
                "occ",
                SCORES,
                "capacity:core_identity:v1",
                vec![],
            ))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("capacity")),
            "got: {err:?}"
        );
    }

    #[tokio::test]
    async fn sqlite_local_rejects_subject_side_revocation() {
        let backend = fresh_backend_with_occurrence("occ").await;
        // A subject-side revocation (writer ∈ subject_key_ids) with NO signature
        // is rejected at admission (§10.1.3 transit-not-rest): it may transit the
        // local tier only on a VALID bound-hybrid signature — never unsigned.
        let err = backend
            .attestation_upsert_local(local_input(
                "occ",
                WITHDRAWS,
                "consent:state:revoked:v1",
                vec!["occ".to_string()],
            ))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("revocation") && m.contains("bound-hybrid signature")),
            "got: {err:?}"
        );
    }

    /// v12.6.0 (CIRISPersist#171, §10.1.3 transit-not-rest) — SQLite parity for
    /// the FULL consent-SLA loop through the REAL admission path: a crypto-valid
    /// subject-side `consent:state:revoked` is ADMITTED as a transit local-tier
    /// write, the revocation scan sees it, and `run_consent_sla_watch` fires
    /// `consent_revocation_promotion_overdue` past the 24 h window (not before).
    /// A crypto-INVALID one is rejected at admission.
    #[tokio::test]
    async fn sqlite_consent_revocation_transit_admits_and_sla_fires_end_to_end() {
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::tier_ingest::test_support::sign_envelope;
        use crate::federation::types::{attestation_tier, attestation_type, LocalAttestationInput};
        use std::time::Duration;
        let backend = fresh_backend_with_occurrence("subject-c").await;
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("target-c", "registry", "target-c"),
            })
            .await
            .unwrap();

        let env = serde_json::json!({
            "id": "rev-c", "dimension": "consent:state:revoked:v1",
            "score": 1.0, "confidence": 0.9,
        });
        let (_hash, sig_classical, sig_pqc) = sign_envelope("subject-c", &env);

        backend
            .attestation_upsert_local(LocalAttestationInput {
                attestation_id: None,
                attesting_key_id: "subject-c".into(),
                attested_key_id: Some("target-c".into()),
                attestation_type: attestation_type::SCORES.into(),
                weight: None,
                expires_at: None,
                attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                    env.clone(),
                )
                .unwrap(),
                subject_key_ids: vec!["subject-c".into()],
                cohort_scope: crate::federation::types::cohort_scope::SELF.to_string(),
                scrub_signature_classical: Some(sig_classical),
                scrub_signature_pqc: sig_pqc,
            })
            .await
            .expect("crypto-valid subject-side revocation transits the local tier");

        let rows = backend.list_consent_revocations(None).await.unwrap();
        assert_eq!(rows.len(), 1, "revocation scan sees the transit row");
        let rev = &rows[0];
        assert_eq!(rev.tier, attestation_tier::LOCAL);
        assert!(rev.promoted_at.is_none());
        assert!(
            !rev.scrub_signature_classical.is_empty() && rev.scrub_signature_pqc.is_some(),
            "transit row round-trips its real bound-hybrid signature"
        );
        let revoked_at = rev.asserted_at;
        let window = Duration::from_secs(86_400);

        let before = revoked_at + chrono::Duration::seconds(86_400 - 1);
        let r = backend.run_consent_sla_watch(before, window).await.unwrap();
        assert_eq!(r.revocations_scanned, 1);
        assert_eq!(r.promotion_overdue, 0, "within window: not overdue");

        let after = revoked_at + chrono::Duration::seconds(86_400 + 1);
        let r = backend.run_consent_sla_watch(after, window).await.unwrap();
        assert_eq!(r.promotion_overdue, 1, "past window: overdue fires");
        let evs = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::CONSENT_REVOCATION_PROMOTION_OVERDUE.into()),
                since: None,
            })
            .await
            .unwrap();
        assert_eq!(evs.len(), 1);
        assert_eq!(evs[0].target_key_id.as_deref(), Some("target-c"));
        assert_eq!(evs[0].subject_key_id.as_deref(), Some("subject-c"));

        // crypto-INVALID revocation → rejected at admission.
        let bad = backend
            .attestation_insert_local(LocalAttestationInput {
                attestation_id: None,
                attesting_key_id: "subject-c".into(),
                attested_key_id: Some("target-c".into()),
                attestation_type: attestation_type::SCORES.into(),
                weight: None,
                expires_at: None,
                attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                    serde_json::json!({
                        "id": "rev-bad", "dimension": "consent:state:revoked:v1",
                        "score": 1.0, "confidence": 0.9,
                    }),
                )
                .unwrap(),
                subject_key_ids: vec!["subject-c".into()],
                cohort_scope: crate::federation::types::cohort_scope::SELF.to_string(),
                scrub_signature_classical: Some("AAAA".into()),
                scrub_signature_pqc: Some("AAAA".into()),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(
                bad,
                crate::federation::Error::FederationTierUnverified { .. }
            ),
            "crypto-invalid revocation rejected at admission, got {bad:?}"
        );
    }

    /// v4.5 attestation_query filters (CEG §10.1.5.4) — dimension prefix,
    /// valid_at, confidence_floor, subject. Raw-inserts federation rows
    /// (bypasses write admission) to exercise the read filters directly.
    #[tokio::test]
    async fn sqlite_attestation_query_filters() {
        use crate::ceg::ReadEngine;
        let backend = fresh_backend_with_occurrence("occ").await;
        let seed = |id: &str, dim: &str, weight: f64, subjects: &[&str], expires: Option<&str>| {
            let conn = backend.conn_handle();
            let conn = conn.lock();
            let env = serde_json::json!({"id": id, "dimension": dim, "score": 1.0}).to_string();
            let subj = serde_json::to_string(subjects).unwrap();
            conn.execute(
                "INSERT INTO federation_attestations (\
                    attestation_id, attesting_key_id, attested_key_id, attestation_type, \
                    weight, asserted_at, expires_at, attestation_envelope, original_content_hash, \
                    scrub_signature_classical, scrub_signature_pqc, scrub_key_id, scrub_timestamp, \
                    pqc_completed_at, persist_row_hash, subject_key_ids, withdraws_admission_rule, \
                    cohort_scope, tier, promoted_at, additional_scrubs\
                 ) VALUES (?1, 'occ', 'occ', 'scores', ?2, '2026-05-01T00:00:00Z', ?3, ?4, x'', \
                          'sig', NULL, 'occ', '2026-05-01T00:00:00Z', NULL, '0', ?5, NULL, \
                          'federation', 'federation', NULL, '[]')",
                rusqlite::params![id, weight, expires, env, subj],
            )
            .unwrap();
        };
        seed("a", "config:filter:v1", 0.9, &[], None);
        seed("b", "config:other:v1", 0.4, &[], None);
        seed(
            "c",
            "goal:x:v1",
            0.95,
            &["subj-1"],
            Some("2030-01-01T00:00:00Z"),
        );
        seed("d", "goal:y:v1", 0.7, &[], Some("2026-05-02T00:00:00Z")); // expires early

        let q = |f: AttestationFilter| {
            let backend = &backend;
            async move {
                let mut ids: Vec<String> = backend
                    .list_attestations(f, None, 100, crate::scope::CallerScope::Unauthenticated)
                    .await
                    .unwrap()
                    .items
                    .into_iter()
                    .map(|a| a.attestation_id)
                    .collect();
                ids.sort();
                ids
            }
        };

        // dimension prefix.
        assert_eq!(
            q(AttestationFilter {
                dimension_prefixes: vec!["config:".into()],
                ..Default::default()
            })
            .await,
            vec!["a", "b"]
        );
        // multiple prefixes OR-combine.
        assert_eq!(
            q(AttestationFilter {
                dimension_prefixes: vec!["config:filter".into(), "goal:".into()],
                ..Default::default()
            })
            .await,
            vec!["a", "c", "d"]
        );
        // confidence floor (NULL excluded; b at 0.4 dropped).
        assert_eq!(
            q(AttestationFilter {
                confidence_floor: Some(0.8),
                ..Default::default()
            })
            .await,
            vec!["a", "c"]
        );
        // subject membership.
        assert_eq!(
            q(AttestationFilter {
                subject_key_id: Some("subj-1".into()),
                ..Default::default()
            })
            .await,
            vec!["c"]
        );
        // valid_at: at 2026-05-03, d has expired (expires 05-02); a/b no expiry, c future.
        let at = "2026-05-03T00:00:00Z".parse().unwrap();
        assert_eq!(
            q(AttestationFilter {
                valid_at: Some(at),
                ..Default::default()
            })
            .await,
            vec!["a", "b", "c"]
        );
        // v17.5.2 (#461) — EXACT dimension match. Pre-fix `dimension_exact` was
        // silently ignored in list_attestations (would return all 4); now
        // `config:filter:v1` matches only `a`, NOT `b` (`config:other:v1`) —
        // proving exact, not prefix.
        assert_eq!(
            q(AttestationFilter {
                dimension_exact: Some("config:filter:v1".into()),
                ..Default::default()
            })
            .await,
            vec!["a"]
        );
        // AND-composed with a prefix set (prefixes OR among themselves, then
        // AND the exact): `config:filter:v1` AND `goal:%` matches nothing.
        assert_eq!(
            q(AttestationFilter {
                dimension_exact: Some("config:filter:v1".into()),
                dimension_prefixes: vec!["goal:".into()],
                ..Default::default()
            })
            .await,
            Vec::<String>::new()
        );
    }

    // ── v17.4.0 (FSD-005 Appendix C) — scores read surface ──────────

    fn scores_base_ts() -> chrono::DateTime<chrono::Utc> {
        chrono::TimeZone::timestamp_opt(&chrono::Utc, 1_700_000_000, 0).unwrap()
    }

    /// Seed the attester key + put a federation `scores` row with full
    /// control over subject / dimension / score / weight / asserted_at.
    #[allow(clippy::too_many_arguments)]
    async fn put_score(
        be: &SqliteBackend,
        id: &str,
        attester: &str,
        subject: &str,
        dimension: &str,
        score: f64,
        weight: f64,
        secs: i64,
    ) {
        // Idempotent-ish: seed the attester key if absent (self-attested).
        let _ = be
            .put_public_key(SignedKeyRecord {
                record: fed_key_with_identity_type(
                    attester,
                    attester,
                    attester,
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await;
        let mut a = signed_attestation_fixture(attester, attester, attester, SCORES);
        a.attestation_id = id.into();
        a.weight = Some(weight);
        a.asserted_at = scores_base_ts() + chrono::Duration::seconds(secs);
        a.attestation_envelope = serde_json::json!({
            "dimension": dimension, "score": score, "confidence": weight,
            "epistemic_mode": "observed",
        });
        a.subject_key_ids = vec![subject.into()];
        a.cohort_scope = "federation".into();
        resign_fed(&mut a); // sign the as-built envelope for the ingest gate
        be.put_attestation(SignedAttestation { attestation: a })
            .await
            .unwrap();
    }

    async fn put_composer(
        be: &SqliteBackend,
        id: &str,
        attester: &str,
        ty: &str,
        references: &str,
        secs: i64,
    ) {
        let _ = be
            .put_public_key(SignedKeyRecord {
                record: fed_key_with_identity_type(
                    attester,
                    attester,
                    attester,
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await;
        let mut a = signed_attestation_fixture(attester, attester, attester, ty);
        a.attestation_id = id.into();
        a.asserted_at = scores_base_ts() + chrono::Duration::seconds(secs);
        a.attestation_envelope = serde_json::json!({
            "references_attestation_id": references, "reason": "t",
        });
        a.subject_key_ids = vec![];
        a.cohort_scope = "federation".into();
        resign_fed(&mut a);
        be.put_attestation(SignedAttestation { attestation: a })
            .await
            .unwrap();
    }

    fn scores_filter(subject: &str) -> AttestationFilter {
        AttestationFilter {
            subject_key_id: Some(subject.into()),
            ..Default::default()
        }
    }

    async fn list_ids(be: &SqliteBackend, f: AttestationFilter) -> Vec<String> {
        use crate::federation::FederationDirectory;
        be.list_scores("", f, None, 100)
            .await
            .unwrap()
            .items
            .into_iter()
            .map(|a| a.attestation_id)
            .collect()
    }

    #[tokio::test]
    async fn sqlite_list_scores_subject_dimension_seek_newest_first() {
        use crate::federation::FederationDirectory;
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        put_score(&be, "s1", "k1", "subj", "trust:demo:v1", 0.5, 1.0, 10).await;
        put_score(&be, "s2", "k2", "subj", "trust:demo:v1", 0.6, 1.0, 20).await;
        put_score(&be, "s3", "k3", "subj", "other:demo:v1", 0.6, 1.0, 30).await;
        // exact dimension seek, newest-first
        let f = AttestationFilter {
            subject_key_id: Some("subj".into()),
            dimension_exact: Some("trust:demo:v1".into()),
            ..Default::default()
        };
        let page = be.list_scores("", f, None, 100).await.unwrap();
        let ids: Vec<_> = page
            .items
            .iter()
            .map(|a| a.attestation_id.clone())
            .collect();
        assert_eq!(ids, vec!["s2", "s1"], "newest-first, dimension-exact");
        // prefix filter picks all trust:* + other:*
        let f = AttestationFilter {
            subject_key_id: Some("subj".into()),
            dimension_prefixes: vec!["trust:".into()],
            ..Default::default()
        };
        let mut ids = list_ids(&be, f).await;
        ids.sort();
        assert_eq!(ids, vec!["s1", "s2"]);
    }

    #[tokio::test]
    async fn sqlite_list_scores_attester_filter_and_cursor() {
        use crate::federation::FederationDirectory;
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        put_score(&be, "a", "k1", "subj", "trust:demo:v1", 0.5, 1.0, 10).await;
        put_score(&be, "b", "k2", "subj", "trust:demo:v1", 0.5, 1.0, 20).await;
        put_score(&be, "c", "k3", "subj", "trust:demo:v1", 0.5, 1.0, 30).await;
        // attester_filter Explicit set membership
        let f = AttestationFilter {
            subject_key_id: Some("subj".into()),
            attester_filter: Some(crate::read::AttesterSet::Explicit(vec![
                "k1".into(),
                "k3".into(),
            ])),
            ..Default::default()
        };
        let mut ids = list_ids(&be, f).await;
        ids.sort();
        assert_eq!(ids, vec!["a", "c"]);
        // cursor pagination stable
        let page1 = be
            .list_scores("", scores_filter("subj"), None, 2)
            .await
            .unwrap();
        assert_eq!(
            page1
                .items
                .iter()
                .map(|a| a.attestation_id.clone())
                .collect::<Vec<_>>(),
            vec!["c", "b"]
        );
        let cur = page1.next_cursor.expect("full page → cursor");
        let page2 = be
            .list_scores("", scores_filter("subj"), Some(cur), 2)
            .await
            .unwrap();
        assert_eq!(
            page2
                .items
                .iter()
                .map(|a| a.attestation_id.clone())
                .collect::<Vec<_>>(),
            vec!["a"]
        );
        assert!(page2.next_cursor.is_none());
    }

    #[tokio::test]
    async fn sqlite_list_scores_lifecycle_hides_withdrawn_by_default() {
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        put_score(&be, "live", "k1", "subj", "trust:demo:v1", 0.5, 1.0, 10).await;
        put_score(&be, "gone", "k2", "subj", "trust:demo:v1", 0.5, 1.0, 20).await;
        put_composer(&be, "w", "k2", WITHDRAWS, "gone", 30).await;
        // default Live → withdrawn "gone" hidden
        let ids = list_ids(&be, scores_filter("subj")).await;
        assert_eq!(ids, vec!["live"], "withdrawn row hidden by default");
        // IncludeWithdrawn → shows it again
        let f = AttestationFilter {
            subject_key_id: Some("subj".into()),
            lifecycle: crate::read::LifecycleView::IncludeWithdrawn,
            ..Default::default()
        };
        let mut ids = list_ids(&be, f).await;
        ids.sort();
        assert_eq!(ids, vec!["gone", "live"]);
    }

    #[tokio::test]
    async fn sqlite_scores_tier_local_hidden_then_shown_and_promote() {
        use crate::federation::FederationDirectory;
        let be = fresh_backend_with_occurrence("occ").await;
        // a local self-scores row (producer authority, tier=local)
        let input = local_input("occ", SCORES, "trust:demo:v1", vec!["subj".into()]);
        let local_id = be.attestation_upsert_local(input).await.unwrap();
        // helper: list as the producing occurrence (local rows are cohort
        // 'self', visible only to their producer).
        let occ_ids = |f: AttestationFilter| {
            let be = &be;
            async move {
                be.list_scores("occ", f, None, 100)
                    .await
                    .unwrap()
                    .items
                    .into_iter()
                    .map(|a| a.attestation_id)
                    .collect::<Vec<_>>()
            }
        };
        // default tier (federation) hides the local row
        assert!(
            occ_ids(scores_filter("subj")).await.is_empty(),
            "local hidden at default federation tier"
        );
        // Tier::Any shows it
        let f = AttestationFilter {
            subject_key_id: Some("subj".into()),
            tier: Some(crate::read::Tier::Any),
            ..Default::default()
        };
        assert_eq!(
            occ_ids(f).await,
            vec![local_id.clone()],
            "Tier::Any reveals local draft"
        );
        // projection row exists at local tier
        let (proj_tier, dim): (String, Option<String>) = {
            let conn = be.conn_handle();
            let conn = conn.lock();
            conn.query_row(
                "SELECT tier, dimension FROM attestation_subjects WHERE attestation_id = ?1",
                [&local_id],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap()
        };
        assert_eq!(proj_tier, "local");
        assert_eq!(dim.as_deref(), Some("trust:demo:v1"));
        // promote → projection flips to federation, now visible at default tier
        be.promote_attestation(
            &local_id,
            crate::federation::types::cohort_scope::FEDERATION,
            "c2ln",
            None,
            "abcdef01",
            "occ",
            chrono::Utc::now(),
        )
        .await
        .unwrap();
        assert_eq!(
            occ_ids(scores_filter("subj")).await,
            vec![local_id],
            "promoted row now federation-visible"
        );
    }

    #[tokio::test]
    async fn sqlite_resolve_scores_latest_wins_withdraw_and_band() {
        use crate::federation::FederationDirectory;
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        // k1: old 0.9 superseded by new 0.4 head; k2: 0.5; k3: withdrawn
        put_score(&be, "k1old", "k1", "subj", "trust:demo:v1", 0.9, 1.0, 10).await;
        put_score(&be, "k1new", "k1", "subj", "trust:demo:v1", 0.4, 1.0, 20).await;
        put_composer(&be, "sup", "k1", "supersedes", "k1old", 20).await;
        put_score(&be, "k2", "k2", "subj", "trust:demo:v1", 0.5, 1.0, 15).await;
        put_score(&be, "k3", "k3", "subj", "trust:demo:v1", 0.5, 1.0, 15).await;
        put_composer(&be, "wd", "k3", WITHDRAWS, "k3", 25).await;
        let v = be
            .resolve_scores(
                "",
                scores_filter("subj"),
                "cc-4.4.2-signed-mean".into(),
                true,
            )
            .await
            .unwrap();
        // live heads: k1new(0.4), k2(0.5) → k3 withdrawn, k1old superseded
        assert_eq!(v.contributor_count, 2);
        // mean(0.4, 0.5) = 0.45 → Supported
        assert_eq!(v.band, crate::read::ConfidenceBand::Supported);
        assert_eq!(v.open_contradictions, 0);
        assert!(v.trace.is_some(), "trace requested");
        assert!(v.age_of_head.is_some());
    }

    #[tokio::test]
    async fn sqlite_resolve_scores_gated_row_excluded() {
        use crate::federation::FederationDirectory;
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        // one federation row (visible) + one 'self'-scoped row (hidden to
        // an unauthenticated caller) — the hidden one must not enter the fold.
        put_score(&be, "vis", "k1", "subj", "trust:demo:v1", 0.5, 1.0, 10).await;
        // self-scoped row via raw insert + projection (bypasses the local-tier
        // write path; it is a federation-tier 'self' cohort row for the gate).
        be.put_public_key(SignedKeyRecord {
            record: fed_key_with_identity_type(
                "k9",
                "k9",
                "k9",
                crate::federation::types::identity_type::AGENT,
            ),
        })
        .await
        .unwrap();
        {
            let conn = be.conn_handle();
            let conn = conn.lock();
            let env =
                serde_json::json!({"dimension":"trust:demo:v1","score":-0.9,"confidence":1.0})
                    .to_string();
            conn.execute(
                "INSERT INTO federation_attestations (attestation_id, attesting_key_id, \
                   attested_key_id, attestation_type, weight, asserted_at, expires_at, \
                   attestation_envelope, original_content_hash, scrub_signature_classical, \
                   scrub_signature_pqc, scrub_key_id, scrub_timestamp, pqc_completed_at, \
                   persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, \
                   tier, promoted_at) VALUES ('hid','k9','k9','scores',1.0,\
                   '2026-01-01T00:00:00Z',NULL,?1,x'','s',NULL,'k9','2026-01-01T00:00:00Z',\
                   NULL,'0','[\"subj\"]',NULL,'self','federation',NULL)",
                rusqlite::params![env],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO attestation_subjects (subject_key_id, dimension, asserted_at, \
                   attestation_id, tier, cohort_scope) VALUES ('subj','trust:demo:v1',\
                   '2026-01-01T00:00:00Z','hid','federation','self')",
                [],
            )
            .unwrap();
        }
        let v = be
            .resolve_scores(
                "",
                scores_filter("subj"),
                "cc-4.4.2-signed-mean".into(),
                false,
            )
            .await
            .unwrap();
        // only the visible k1 row counts (the self-scoped -0.9 is gated out).
        assert_eq!(v.contributor_count, 1);
        assert_eq!(v.band, crate::read::ConfidenceBand::Supported);
    }

    #[tokio::test]
    async fn sqlite_list_attestation_log_owner_scope_invariants() {
        // #455 — the owner LOG walk must (a) IGNORE the caller gate — see a
        // 'self'-cohort row a gated `list_scores` hides; (b) be lifecycle-
        // BLIND — return a withdrawn score AND its composer; (c) be
        // federation-tier ONLY — exclude local drafts.
        use crate::federation::FederationDirectory;
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        put_score(&be, "live", "k1", "subj", "trust:demo:v1", 0.5, 1.0, 10).await;
        put_score(&be, "gone", "k2", "subj", "trust:demo:v1", 0.5, 1.0, 20).await;
        put_composer(&be, "wd", "k2", WITHDRAWS, "gone", 30).await;
        // a 'self'-cohort federation row the caller-gated read hides.
        be.put_public_key(SignedKeyRecord {
            record: fed_key_with_identity_type(
                "k9",
                "k9",
                "k9",
                crate::federation::types::identity_type::AGENT,
            ),
        })
        .await
        .unwrap();
        {
            let conn = be.conn_handle();
            let conn = conn.lock();
            let env = serde_json::json!({"dimension":"trust:demo:v1","score":0.3}).to_string();
            conn.execute(
                "INSERT INTO federation_attestations (attestation_id, attesting_key_id, \
                   attested_key_id, attestation_type, weight, asserted_at, expires_at, \
                   attestation_envelope, original_content_hash, scrub_signature_classical, \
                   scrub_signature_pqc, scrub_key_id, scrub_timestamp, pqc_completed_at, \
                   persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, \
                   tier, promoted_at) VALUES ('hid','k9','k9','scores',1.0,\
                   '2026-01-01T00:00:00Z',NULL,?1,x'','s',NULL,'k9','2026-01-01T00:00:00Z',\
                   NULL,'0','[\"subj\"]',NULL,'self','federation',NULL)",
                rusqlite::params![env],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO attestation_subjects (subject_key_id, dimension, asserted_at, \
                   attestation_id, tier, cohort_scope) VALUES ('subj','trust:demo:v1',\
                   '2026-01-01T00:00:00Z','hid','federation','self')",
                [],
            )
            .unwrap();
        }
        // a LOCAL-tier draft on the same subject (raw insert) — the replicable
        // log is federation-tier only, so it must NOT appear.
        {
            let conn = be.conn_handle();
            let conn = conn.lock();
            let env = serde_json::json!({"dimension":"trust:demo:v1","score":0.1}).to_string();
            conn.execute(
                "INSERT INTO federation_attestations (attestation_id, attesting_key_id, \
                   attested_key_id, attestation_type, weight, asserted_at, expires_at, \
                   attestation_envelope, original_content_hash, scrub_signature_classical, \
                   scrub_signature_pqc, scrub_key_id, scrub_timestamp, pqc_completed_at, \
                   persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, \
                   tier, promoted_at) VALUES ('loc','k1','k1','scores',1.0,\
                   '2026-01-02T00:00:00Z',NULL,?1,x'','','NULL','k1','2026-01-02T00:00:00Z',\
                   NULL,'rowhash','[\"subj\"]',NULL,'self','local',NULL)",
                rusqlite::params![env],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO attestation_subjects (subject_key_id, dimension, asserted_at, \
                   attestation_id, tier, cohort_scope) VALUES ('subj','trust:demo:v1',\
                   '2026-01-02T00:00:00Z','loc','local','self')",
                [],
            )
            .unwrap();
        }

        // Gated consumer read (unauthenticated, Live): only "live".
        let gated = list_ids(&be, scores_filter("subj")).await;
        assert_eq!(gated, vec!["live"], "gate+lifecycle hide gone/hid/local");

        // Owner LOG walk, SUBJECT seek: NO gate, lifecycle-blind,
        // federation-only. Returns the subject-bearing federation rows — gone
        // (withdrawn, still present) + hid (self-cohort, ungated) + live — but
        // NOT the subjectless 'wd' composer (no subject to seek on) nor the
        // 'loc' local-tier draft.
        let log = be
            .list_attestation_log(Some("subj"), None, 100)
            .await
            .unwrap();
        let mut ids: Vec<_> = log.items.iter().map(|a| a.attestation_id.clone()).collect();
        ids.sort();
        assert_eq!(
            ids,
            vec!["gone", "hid", "live"],
            "subject log = subject-bearing FEDERATION rows, ungated + lifecycle-blind, local excluded"
        );
        assert!(log.items.iter().all(|a| !a.persist_row_hash.is_empty()));

        // Owner LOG walk, FULL (subject = None): the whole federation log for
        // anti-entropy — the subjectless 'wd' composer IS here (composers must
        // replicate); the 'loc' local draft still is NOT (federation-only).
        let full = be.list_attestation_log(None, None, 100).await.unwrap();
        let mut fids: Vec<_> = full
            .items
            .iter()
            .map(|a| a.attestation_id.clone())
            .collect();
        fids.sort();
        assert_eq!(
            fids,
            vec!["gone", "hid", "live", "wd"],
            "full log = every federation row incl. subjectless composers; local excluded"
        );
        assert!(
            !fids.contains(&"loc".to_string()),
            "local draft excluded from full log"
        );
    }

    #[tokio::test]
    async fn sqlite_v106_backfill_projects_existing_rows() {
        let be = SqliteBackend::open_in_memory().await.unwrap();
        be.run_migrations().await.unwrap();
        // Raw-insert a federation row with two subjects WITHOUT touching the
        // projection, then simulate the backfill on a cleared projection.
        be.put_public_key(SignedKeyRecord {
            record: fed_key_with_identity_type(
                "k1",
                "k1",
                "k1",
                crate::federation::types::identity_type::AGENT,
            ),
        })
        .await
        .unwrap();
        {
            let conn = be.conn_handle();
            let conn = conn.lock();
            let env = serde_json::json!({"dimension":"trust:demo:v1","score":1.0}).to_string();
            conn.execute(
                "INSERT INTO federation_attestations (attestation_id, attesting_key_id, \
                   attested_key_id, attestation_type, weight, asserted_at, expires_at, \
                   attestation_envelope, original_content_hash, scrub_signature_classical, \
                   scrub_signature_pqc, scrub_key_id, scrub_timestamp, pqc_completed_at, \
                   persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, \
                   tier, promoted_at) VALUES ('bf','k1','k1','scores',1.0,\
                   '2026-01-01T00:00:00Z',NULL,?1,x'','s',NULL,'k1','2026-01-01T00:00:00Z',\
                   NULL,'0','[\"p\",\"q\"]',NULL,'federation','federation',NULL)",
                rusqlite::params![env],
            )
            .unwrap();
            conn.execute("DELETE FROM attestation_subjects", [])
                .unwrap();
            // the V106 backfill statement (verbatim shape).
            conn.execute(
                "INSERT INTO attestation_subjects (subject_key_id, dimension, asserted_at, \
                    attestation_id, tier, cohort_scope) \
                 SELECT je.value, json_extract(fa.attestation_envelope,'$.dimension'), \
                    fa.asserted_at, fa.attestation_id, fa.tier, fa.cohort_scope \
                 FROM federation_attestations fa, json_each(fa.subject_key_ids) je",
                [],
            )
            .unwrap();
            let mut subs: Vec<String> = {
                let mut stmt = conn
                    .prepare("SELECT subject_key_id FROM attestation_subjects WHERE attestation_id='bf' ORDER BY subject_key_id")
                    .unwrap();
                stmt.query_map([], |r| r.get::<_, String>(0))
                    .unwrap()
                    .collect::<Result<_, _>>()
                    .unwrap()
            };
            subs.sort();
            assert_eq!(subs, vec!["p".to_string(), "q".to_string()]);
        }
    }

