    // ─── v4.7.0 (CIRISPersist#177) — typed register_accord_public_key ──

    /// SQLite round-trip for the typed key-registration outcome: a new
    /// key → `Registered`; the same key+pubkey → `AlreadyRegistered`; the
    /// same key with a *different* pubkey → `RotationCollision` carrying
    /// the SHA-256 fingerprint of the **stored** (original) pubkey.
    #[tokio::test]
    async fn sqlite_register_accord_public_key_classifies_outcomes() {
        use crate::store::{accord_key_fingerprint, KeyRegistrationOutcome};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        let reg = backend
            .register_accord_public_key("agent-k", "pubA", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        assert_eq!(reg, KeyRegistrationOutcome::Registered);

        let again = backend
            .register_accord_public_key("agent-k", "pubA", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        assert_eq!(
            again,
            KeyRegistrationOutcome::AlreadyRegistered,
            "same key+pubkey is the idempotent reboot path"
        );

        let collision = backend
            .register_accord_public_key("agent-k", "pubB", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        match collision {
            KeyRegistrationOutcome::RotationCollision {
                existing_key_fingerprint,
            } => assert_eq!(
                existing_key_fingerprint,
                accord_key_fingerprint("pubA"),
                "fingerprint is of the STORED key, not the incoming one"
            ),
            other => panic!("expected RotationCollision, got {other:?}"),
        }
        // The collision is non-destructive: the stored pubkey is unchanged.
        let stored: String = {
            let conn = backend.conn_handle();
            let conn = conn.lock();
            conn.query_row(
                "SELECT public_key_base64 FROM accord_public_keys WHERE key_id = 'agent-k'",
                [],
                |r| r.get(0),
            )
            .unwrap()
        };
        assert_eq!(stored, "pubA", "rotation collision must not overwrite");
    }

    // ─── BlobStorage tests (v2.3, CIRISPersist#103) ────────────────

    use crate::federation::{
        BlobBody, BlobError, BlobRange, BlobStorage, ExternalRef, PutBlobAttestation,
    };

    fn blob_attestation(
        attesting_key_id: &str,
        scrub_key_id: &str,
        attestation_id: &str,
    ) -> PutBlobAttestation {
        // v3.0.0 (CIRISPersist#116, CEG 0.2 §10.1.2): use Utc::now()
        // so the row lands inside the DEFAULT_HOLDS_BYTES_TTL window
        // — `list_holders` now filters TTL-expired rows.
        PutBlobAttestation {
            attesting_key_id: attesting_key_id.into(),
            attestation_id: attestation_id.into(),
            original_content_hash_hex: "abcdef01".into(),
            scrub_signature_classical: "c2ln".into(),
            scrub_signature_pqc: None,
            scrub_key_id: scrub_key_id.into(),
            scrub_timestamp: chrono::Utc::now(),
        }
    }

    async fn blob_test_backend() -> SqliteBackend {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        // Bootstrap a federation key so the FK on holds_bytes
        // attestation's attesting_key_id is satisfied.
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("host-a", "primitive-a", "host-a"),
            })
            .await
            .unwrap();
        // v9.3.0 (#247) — put_blob_signing's holds_bytes scrub_key_id is
        // host-a's DERIVED federation key_id; register that row too
        // (keyed by the derived id, carrying host-a's real pubkeys).
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key_derived("host-a"),
            })
            .await
            .unwrap();
        backend
    }

    fn sha256_of(bytes: &[u8]) -> [u8; 32] {
        use sha2::{Digest, Sha256};
        let d = Sha256::digest(bytes);
        let mut out = [0u8; 32];
        out.copy_from_slice(&d);
        out
    }

    #[tokio::test]
    async fn blob_inline_round_trip() {
        let backend = blob_test_backend().await;
        let bytes = b"hello blob world".to_vec();
        let sha = sha256_of(&bytes);
        backend
            .put_blob(
                &sha,
                BlobBody::Inline(bytes.clone()),
                Some("application/octet-stream"),
                blob_attestation(
                    "host-a",
                    "host-a",
                    uuid::Uuid::new_v4().to_string().as_str(),
                ),
            )
            .await
            .expect("put inline");
        let got = backend.get_blob(&sha).await.expect("get").expect("present");
        assert_eq!(got, BlobBody::Inline(bytes));
    }

