    // Regression for CIRISPersist#130 reopen: list_holders must
    // report a locally-held blob's holder even when the holds_bytes
    // attestation was emitted with a stale timestamp (older than the
    // CEG §10.1.2 24h TTL). The bytes-on-disk in federation_blobs
    // are definitive proof of holding; freshness window only applies
    // to peer-discovered attestations where we lack the bytes.
    //
    // Closes the child-safety hole in cirisnode_process_takedown_-
    // admission, which calls list_holders internally — stale-attested
    // local content would otherwise evade NCMEC/CSAM/CourtOrder
    // eviction.
    #[tokio::test]
    async fn blob_list_holders_stale_local_repro_130() {
        use crate::federation::BlobStorage;
        let backend = evict_test_backend_with_actors(&["actor-a"]).await;
        let signer = test_signer_for("actor-a");
        let bytes = b"signed payload".to_vec();
        let sha = sha256_of(&bytes);
        let stale_ts = chrono::Utc::now() - chrono::Duration::hours(48);
        backend
            .put_blob_signing(
                &sha,
                BlobBody::Inline(bytes),
                None,
                "actor-a",
                &blob_signer(&signer),
                stale_ts,
                uuid::Uuid::new_v4(),
            )
            .await
            .unwrap();
        let holders = backend.list_holders(&sha).await.unwrap();
        assert_eq!(
            holders,
            vec!["actor-a".to_string()],
            "list_holders must include local writer even with stale attestation"
        );
    }

    // ── #153 Ask 5: holds_bytes suppression for self/family ────────

    /// store_blob_local persists the bytes but emits NO holds_bytes
    /// attestation — the structural-invisibility primitive. get_blob
    /// returns the bytes; list_holders is empty (nothing announced).
    #[tokio::test]
    async fn store_blob_local_persists_bytes_without_announcing() {
        use crate::federation::BlobStorage;
        let backend = blob_test_backend().await;
        let bytes = b"family photo".to_vec();
        let sha = sha256_of(&bytes);
        backend
            .store_blob_local(&sha, BlobBody::Inline(bytes.clone()), None)
            .await
            .unwrap();
        // Bytes are stored + readable locally.
        match backend.get_blob(&sha).await.unwrap() {
            Some(BlobBody::Inline(got)) => assert_eq!(got, bytes),
            other => panic!("expected inline bytes, got {other:?}"),
        }
        // But nothing is announced to the federation.
        assert!(
            backend.list_holders(&sha).await.unwrap().is_empty(),
            "self/family content must emit no holds_bytes attestation"
        );
    }

    /// put_blob_signing_scoped("self", ...) dispatches to local-only
    /// storage: bytes stored, no holds_bytes, signer never consulted.
