    /// #369 (CC 4.5.4 / §11.11) — no-moderator federation-APPLY gate,
    /// broadened keying, END-TO-END through `put_attestation` (sqlite; parity
    /// with memory's decision table + the postgres twin). A federation-tier
    /// row attested TO a stored moderator-less community (the membership
    /// shape — NO `community_id` envelope field) is refused fail-secure;
    /// the same shape onto a moderatored community lands; local-tier +
    /// storage-only community ops stay untouched.
    #[tokio::test]
    async fn no_moderator_federate_apply_broadened_keying_sqlite() {
        use crate::federation::admission::MEMBER_ROLE_FOUNDER;
        use crate::federation::types::{consensus_protocol, identity_type};
        use crate::federation::FederationDirectory;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        // Keys: a USER founder (steward-bound ⇒ zero-hop moderator), a
        // PRIMITIVE founder (passes the storage steward-binding gate — not
        // node/agent — but is NOT steward-bound ⇒ no moderator), + the two
        // community keys.
        for (kid, ity) in [
            ("nm-user", identity_type::USER),
            ("nm-prim", identity_type::PRIMITIVE),
            ("nm-ok", identity_type::PRIMITIVE),
            ("nm-no", identity_type::PRIMITIVE),
        ] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key_with_identity_type(kid, "nm", kid, ity),
                })
                .await
                .unwrap();
        }
        let put_comm = |cid: &str, founder: &str| {
            crate::federation::tier_ingest::test_support::sign_community(
                cid,
                crate::federation::Community {
                    community_key_id: cid.into(),
                    community_name: "nm-test".into(),
                    members: vec![crate::federation::CommunityMember {
                        key_id: founder.into(),
                        joined_at: "2026-06-04T00:00:00Z".parse().unwrap(),
                        role: Some(MEMBER_ROLE_FOUNDER.into()),
                    }],
                    founded_at: "2026-06-04T00:00:00Z".parse().unwrap(),
                    consensus_protocol: consensus_protocol::FOUNDER_ONLY.into(),
                    policy_blob: None,
                    persist_row_hash: String::new(),
                },
            )
        };
        // Storage-only put_community is NOT the federate gate — both records
        // (moderatored AND moderator-less) store fine.
        backend
            .put_community(put_comm("nm-ok", "nm-user"))
            .await
            .unwrap();
        backend
            .put_community(put_comm("nm-no", "nm-prim"))
            .await
            .unwrap();

        // (1) Membership shape onto the moderator-less community → REFUSED
        //     fail-secure, nothing stored.
        let err = backend
            .put_attestation(SignedAttestation {
                attestation: fed_attestation("nm-a1", "nm-prim", "nm-no", "nm-prim"),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(
                err,
                crate::federation::Error::CommunityHasNoModerator { .. }
            ),
            "federation apply keyed on a moderator-less community must refuse, got {err:?}"
        );
        assert_eq!(err.kind(), "federation_community_no_moderator");
        assert!(
            crate::federation::FederationDirectory::list_attestations_for(&backend, "nm-no")
                .await
                .unwrap()
                .is_empty()
        );

        // (2) Same shape onto the MODERATORED community → ADMITTED + stored.
        backend
            .put_attestation(SignedAttestation {
                attestation: fed_attestation("nm-a2", "nm-user", "nm-ok", "nm-user"),
            })
            .await
            .expect("moderatored community continues to federate");
        assert_eq!(
            crate::federation::FederationDirectory::list_attestations_for(&backend, "nm-ok")
                .await
                .unwrap()
                .len(),
            1
        );

        // (3) LOCAL-tier row keyed on the moderator-less community →
        //     untouched (not a federation apply step).
        let mut local = fed_attestation("nm-a3", "nm-prim", "nm-no", "nm-prim");
        local.tier = crate::federation::types::attestation_tier::LOCAL.into();
        local.cohort_scope = crate::federation::types::cohort_scope::SELF.into();
        backend
            .put_attestation(SignedAttestation { attestation: local })
            .await
            .expect("local-tier row is not a federation apply step");

        // (4) Storage-only membership op on the moderator-less community →
        //     untouched (loss-processing / recovery must not be blocked).
        backend
            .put_community_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                    "nm-no",
                    crate::federation::CommunityMembershipRevocation {
                        community_key_id: "nm-no".into(),
                        removed_identity_key_id: "nm-prim".into(),
                        removed_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                        effective_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                        reason: None,
                        witness_set: Vec::new(),
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .expect("membership revocation is storage, not a federation apply step");

        // (5) The drivable verdict mirrors the apply decision.
        let v = crate::federation::admission::no_moderator_federate_verdict(&backend, "nm-no")
            .await
            .unwrap();
        assert_eq!(
            v,
            serde_json::json!({
                "admitted": false, "community_known": true,
                "reason": "federation_community_no_moderator"
            })
        );
        let v = crate::federation::admission::no_moderator_federate_verdict(&backend, "nm-ok")
            .await
            .unwrap();
        assert_eq!(
            v,
            serde_json::json!({ "admitted": true, "community_known": true })
        );
    }

    /// v11.5.0 (CIRISPersist#306, CC 3.2 / CC 3.3.12 / CC 1.15.6) — sqlite
    /// parity for the I1 age band, the user-target steward-binding gate, and
    /// the minor-stewardship liveness fail-secure.
    #[tokio::test]
    async fn user_target_gate_and_minor_liveness_sqlite() {
        use crate::federation::admission::{is_steward_bound, steward_bindings_of};
        use crate::federation::age::{age_band, AgeBand};
        use crate::federation::types::{attestation_type, delegation_scope as ds, identity_type};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        for (k, ity) in [
            ("sl-witness", identity_type::WITNESS),
            ("sl-S", identity_type::USER), // adult-user steward
            ("sl-A", identity_type::USER), // self-sovereign adult user
            ("sl-M", identity_type::USER), // minor-user ward
            ("sl-N", identity_type::NODE), // node control
        ] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key_with_identity_type(k, k, k, ity),
                })
                .await
                .unwrap();
        }

        // Age-attest S + A as adults (witness rung), M as a minor.
        let age = |emitter: &str, subj: &str, token: &str| {
            let mut a = topo_attestation(
                emitter,
                subj,
                token,
                None,
                None,
                &[],
                None,
                chrono::Utc::now(),
            );
            a.attestation_envelope = serde_json::json!({ "id": token });
            resign_fed(&mut a);
            a
        };
        for (subj, token) in [
            ("sl-S", "age_assurance:provider:adult:v1"),
            ("sl-A", "age_assurance:provider:adult:v1"),
            ("sl-M", "age_assurance:provider:minor:v1"),
        ] {
            backend
                .put_attestation(SignedAttestation {
                    attestation: age("sl-witness", subj, token),
                })
                .await
                .unwrap();
        }
        assert_eq!(age_band(&backend, "sl-A").await.unwrap(), AgeBand::Adult);
        assert_eq!(age_band(&backend, "sl-M").await.unwrap(), AgeBand::Minor);

        // user-target gate: S(adult) → A(adult user) REJECTED (self-sovereign).
        let e = backend
            .put_attestation(SignedAttestation {
                attestation: node_delegates_to_sqlite("sl-S", "sl-A", &[ds::INFRA_SERVE]),
            })
            .await
            .unwrap_err();
        assert_eq!(e.kind(), "federation_user_target_steward_binding_forbidden");

        // A steward-less minor does NOT self-anchor (fail-secure).
        assert!(!is_steward_bound(&backend, "sl-M").await.unwrap());
        // An adult user self-anchors with no edge.
        assert!(is_steward_bound(&backend, "sl-A").await.unwrap());

        // S(adult) → M(minor) ADMITTED; minor becomes steward-bound to S only.
        backend
            .put_attestation(SignedAttestation {
                attestation: node_delegates_to_sqlite("sl-S", "sl-M", &[ds::INFRA_SERVE]),
            })
            .await
            .expect("adult-user steward → minor ward admitted");
        assert!(is_steward_bound(&backend, "sl-M").await.unwrap());
        assert_eq!(
            steward_bindings_of(&backend, "sl-M").await.unwrap(),
            vec!["sl-S".to_string()],
        );

        // S withdraws → the minor fails secure (false).
        let mut w = topo_attestation(
            "sl-S",
            "sl-M",
            attestation_type::WITHDRAWS,
            None,
            None,
            &[],
            None,
            chrono::Utc::now(),
        );
        w.attestation_envelope = serde_json::json!({ "id": "sl-withdraw" });
        resign_fed(&mut w);
        backend
            .put_attestation(SignedAttestation { attestation: w })
            .await
            .unwrap();
        assert!(
            !is_steward_bound(&backend, "sl-M").await.unwrap(),
            "a minor whose only adult steward was withdrawn must fail secure",
        );
    }

    /// CC 3.4.12 (CIRISPersist#309) — adult-incapacity binding + fail-to-liberty
    /// on the SQLITE backend (pg/sqlite symmetry): the shared admission gate
    /// admits a scoped, reversible-excluded, bounded binding; a lapsed
    /// `valid_until` is non-live and the adult auto-re-sovereigns.
    #[tokio::test]
    async fn adult_incapacity_binding_and_fail_to_liberty_sqlite() {
        use crate::federation::admission::steward_bindings_of;
        use crate::federation::types::{attestation_type, identity_type};
        use chrono::{Duration, Utc};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        for (k, ity) in [
            ("si-assessor", identity_type::WITNESS),
            ("si-S", identity_type::USER),
            ("si-A", identity_type::USER),
        ] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key_with_identity_type(k, k, k, ity),
                })
                .await
                .unwrap();
        }

        // A capacity/age attestation ABOUT `subj` from `emitter` carrying a
        // bare `attestation_type` token (like the age fixtures).
        let att = |emitter: &str, subj: &str, token: &str| {
            let mut a = topo_attestation(emitter, subj, token, None, None, &[], None, Utc::now());
            a.attestation_envelope = serde_json::json!({ "id": token });
            resign_fed(&mut a);
            a
        };
        for (subj, token) in [
            ("si-S", "age_assurance:provider:adult:v1"),
            ("si-A", "age_assurance:provider:adult:v1"),
        ] {
            backend
                .put_attestation(SignedAttestation {
                    attestation: att("si-assessor", subj, token),
                })
                .await
                .unwrap();
        }
        for token in [
            "capacity_assurance:panel:financial:incapacitated:v1",
            "capacity_assurance:reversible_excluded:financial",
        ] {
            backend
                .put_attestation(SignedAttestation {
                    attestation: att("si-assessor", "si-A", token),
                })
                .await
                .expect("witness capacity attestation admitted on sqlite");
        }

        // An adult-incapacity binding with the CC 3.4.12 envelope fields.
        let binding = |id: &str, valid_until: &str| {
            let mut a = topo_attestation(
                "si-S",
                "si-A",
                attestation_type::DELEGATES_TO,
                None,
                None,
                &[],
                None,
                Utc::now(),
            );
            a.attestation_envelope = serde_json::json!({
                "id": id,
                "scope": ["financial"],
                "binding_legitimacy_source": "prior_will_proxy",
                "valid_until": valid_until,
            });
            resign_fed(&mut a);
            a
        };

        // LIVE binding (future valid_until) → S is a live anchor of A.
        let future = (Utc::now() + Duration::days(30)).to_rfc3339();
        backend
            .put_attestation(SignedAttestation {
                attestation: binding("si-live", &future),
            })
            .await
            .expect("valid adult-incapacity binding admitted on sqlite");
        assert!(steward_bindings_of(&backend, "si-A")
            .await
            .unwrap()
            .contains(&"si-S".to_string()));

        // Fail-to-liberty: a fresh ward whose ONLY binding has lapsed.
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key_with_identity_type("si-B", "si-B", "si-B", identity_type::USER),
            })
            .await
            .unwrap();
        backend
            .put_attestation(SignedAttestation {
                attestation: att("si-assessor", "si-B", "age_assurance:provider:adult:v1"),
            })
            .await
            .unwrap();
        for token in [
            "capacity_assurance:panel:financial:incapacitated:v1",
            "capacity_assurance:reversible_excluded:financial",
        ] {
            backend
                .put_attestation(SignedAttestation {
                    attestation: att("si-assessor", "si-B", token),
                })
                .await
                .unwrap();
        }
        let lapsed = (Utc::now() - Duration::days(1)).to_rfc3339();
        let mut b = topo_attestation(
            "si-S",
            "si-B",
            attestation_type::DELEGATES_TO,
            None,
            None,
            &[],
            None,
            Utc::now(),
        );
        b.attestation_envelope = serde_json::json!({
            "id": "si-lapsed",
            "scope": ["financial"],
            "binding_legitimacy_source": "prior_will_proxy",
            "valid_until": lapsed,
        });
        resign_fed(&mut b);
        backend
            .put_attestation(SignedAttestation { attestation: b })
            .await
            .expect("lapsed-valid_until binding structurally admitted");
        let anchors = steward_bindings_of(&backend, "si-B").await.unwrap();
        assert!(
            !anchors.contains(&"si-S".to_string()),
            "a lapsed binding confers no standing (fail-to-liberty)"
        );
        assert_eq!(
            anchors,
            vec!["si-B".to_string()],
            "adult auto-re-sovereigns"
        );
    }

    /// SecReview F3: a WITHDRAWN `delegates_to(user → node)` no longer
    /// confers steward-binding (sqlite parity) — admitted while live, REJECTED
    /// after the granter withdraws the edge.
    #[tokio::test]
    async fn community_steward_binding_withdrawn_delegation_not_live_sqlite() {
        use crate::federation::types::{attestation_type, delegation_scope as ds};
        let backend = bootstrap_node_agency_sqlite().await;
        let d = node_delegates_to_sqlite(
            "owner",
            "node-key",
            &[ds::INFRA_SERVE, ds::INFRA_NETWORK_PRESENCE],
        );
        let d_id = d.attestation_id.clone();
        backend
            .put_attestation(SignedAttestation { attestation: d })
            .await
            .unwrap();
        put_community_ob_sqlite(&backend, "comm-ob-wd-live", vec!["node-key"], None)
            .await
            .expect("steward-bound (live) node admitted");

        // owner withdraws the edge (issuer-against-recipient: attested = node-key).
        let mut w = topo_attestation(
            "owner",
            "node-key",
            attestation_type::WITHDRAWS,
            None,
            None,
            &[],
            None,
            chrono::Utc::now(),
        );
        w.attestation_envelope = serde_json::json!({"references_attestation_id": d_id});
        resign_fed(&mut w);
        backend
            .put_attestation(SignedAttestation { attestation: w })
            .await
            .expect("owner withdraws own delegation edge");

        let err = put_community_ob_sqlite(&backend, "comm-ob-wd-dead", vec!["node-key"], None)
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::Error::UnstewardedCommunityMember { .. }
        ));
        assert!(backend
            .lookup_community("comm-ob-wd-dead")
            .await
            .unwrap()
            .is_none());
    }

