    // ── v3.6.0 (CIRISPersist#134, CEG 0.3 §11.5.3) — trusted-publisher chain ──

    /// CEG 0.3 §11.5.3: `lookup_trusted_publisher_chain` returns an
    /// empty vector when no `trusted_publisher`-type key has emitted a
    /// `content_rating:*` attestation referencing the SHA.
    #[tokio::test]
    async fn lookup_trusted_publisher_chain_returns_empty_for_unblessed_content() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let sha_hex = "a".repeat(64);
        let chain = backend
            .lookup_trusted_publisher_chain(&sha_hex)
            .await
            .unwrap();
        assert!(chain.is_empty(), "no publishers seeded → empty chain");
    }

    /// CEG 0.3 §11.5.3: seed a `trusted_publisher`-type key + a
    /// `content_rating:*` attestation referencing the SHA; the chain
    /// includes the attestation.
    #[tokio::test]
    async fn lookup_trusted_publisher_chain_returns_chain_when_trusted_publisher_attests() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let publisher_key = "pub-1";
        let sha_hex = "b".repeat(64);
        let other_sha = "c".repeat(64);
        // Seed the publisher key as trusted_publisher identity_type —
        // CONFERRED by the accord family, not self-declared (CIRISPersist#543):
        // `trusted_publisher` rates OTHER parties' content, so a self-asserted
        // claim is refused at every write chokepoint.
        crate::federation::operational::test_support::put_accord_conferred_key(
            &backend,
            fed_key_with_identity_type(
                publisher_key,
                publisher_key,
                publisher_key,
                crate::federation::types::identity_type::TRUSTED_PUBLISHER,
            ),
        )
        .await
        .unwrap();
        // Seed a content_rating attestation referencing the target SHA.
        let mut hit = fed_attestation("att-hit", publisher_key, publisher_key, publisher_key);
        hit.attestation_envelope = serde_json::json!({
            "dimension": "content_rating:mpa:pg13:v1",
            "score": 1.0,
            "confidence": 0.9,
            "evidence_refs": [sha_hex],
        });
        resign_fed(&mut hit); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        backend
            .put_attestation(SignedAttestation { attestation: hit })
            .await
            .unwrap();
        // Seed a different content_rating referencing a different SHA —
        // must NOT appear in the result.
        let mut miss = fed_attestation("att-miss", publisher_key, publisher_key, publisher_key);
        miss.attestation_envelope = serde_json::json!({
            "dimension": "content_rating:mpa:r:v1",
            "score": 1.0,
            "confidence": 0.9,
            "evidence_refs": [other_sha],
        });
        resign_fed(&mut miss); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        backend
            .put_attestation(SignedAttestation { attestation: miss })
            .await
            .unwrap();

        let chain = backend
            .lookup_trusted_publisher_chain(&sha_hex)
            .await
            .unwrap();
        assert_eq!(chain.len(), 1, "exactly one matching attestation");
        assert_eq!(chain[0].attestation_id, "att-hit");
        assert_eq!(chain[0].attesting_key_id, publisher_key);
        let dim = chain[0]
            .attestation_envelope
            .get("dimension")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        assert!(dim.starts_with("content_rating:"));
    }

    /// CEG 0.3 §11.5.3: non-`trusted_publisher` identities cannot
    /// emit `content_rating:*` attestations (the reserved-prefix
    /// admission gate would reject them on put_attestation). The chain
    /// accessor reads through `trusted_publisher` keys only, so a
    /// rogue agent's bypass attempt would still not surface here.
    #[tokio::test]
    async fn lookup_trusted_publisher_chain_ignores_non_publisher_emitters() {
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        // Seed a steward (not trusted_publisher).
        let steward_key = "steward-1";
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key_with_identity_type(
                    steward_key,
                    steward_key,
                    steward_key,
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();
        // Steward's attestation under content_rating:* would be
        // rejected by the admission gate in production. For this
        // test, we bypass put_attestation's emitter check via a non-
        // content_rating dimension so the row lands, then assert the
        // accessor still returns empty (steward isn't a publisher).
        let sha_hex = "d".repeat(64);
        let mut att = fed_attestation("att-steward", steward_key, steward_key, steward_key);
        att.attestation_envelope = serde_json::json!({
            "dimension": "identity_binding:v1",
            "score": 1.0,
            "confidence": 0.9,
            "evidence_refs": [sha_hex],
        });
        resign_fed(&mut att); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        backend
            .put_attestation(SignedAttestation { attestation: att })
            .await
            .unwrap();
        let chain = backend
            .lookup_trusted_publisher_chain(&sha_hex)
            .await
            .unwrap();
        assert!(chain.is_empty(), "steward isn't a trusted_publisher");
    }

    /// CIRISConformance#11 round 2, Finding B — the repository-statistics
    /// cache is per-backend-instance, never a process global.
    ///
    /// Two independent backends over the same empty 1-day window: each
    /// backend's FIRST call is a fresh compute (`cache_hit: false`) and
    /// its SECOND is a hit (`cache_hit: true`) — symmetrically. Backend
    /// B's first call must NOT hit backend A's entry (the round-2 report
    /// saw a fresh engine served a prior engine's cached row). The
    /// pre-fix process-global cache made B's first call a poisoned hit.
    #[tokio::test]
    async fn repo_stats_cache_is_per_backend_not_global() {
        use crate::ceg::aggregates::repository::RepositoryFilter;
        use crate::ceg::types::TimeWindow;
        use crate::scope::CallerScope;

        let window = TimeWindow::new(
            Utc.timestamp_opt(0, 0).unwrap(),
            Utc.timestamp_opt(86_400, 0).unwrap(), // 1-day window
        )
        .unwrap();
        let filter = RepositoryFilter {
            window,
            agent_id_hashes: vec![],
            deployment_domains: vec![],
            cohort_scope_in: vec![],
            task_classes: vec![],
            fragility_only: false,
        };

        let a = SqliteBackend::open_in_memory().await.unwrap();
        a.run_migrations().await.unwrap();
        let b = SqliteBackend::open_in_memory().await.unwrap();
        b.run_migrations().await.unwrap();

        // Backend A: first call is a miss (fresh compute).
        let a1 = a
            .get_repository_statistics(filter.clone(), CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert!(!a1.cache_hit, "A first call must be a fresh compute");

        // Backend A: second call is a hit on A's own entry.
        let a2 = a
            .get_repository_statistics(filter.clone(), CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert!(a2.cache_hit, "A second call must hit A's cache");
        assert_eq!(
            a1.evaluated_at_unix_ms, a2.evaluated_at_unix_ms,
            "A's hit preserves the cached evaluation time"
        );

        // Backend B: first call must be a fresh compute, NOT a poisoned
        // hit on A's entry (the cross-backend leak the global caused).
        let b1 = b
            .get_repository_statistics(filter.clone(), CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert!(
            !b1.cache_hit,
            "B first call must be a fresh compute, not a hit on A's cache"
        );

        // Backend B: second call hits B's own entry — symmetric with A.
        let b2 = b
            .get_repository_statistics(filter.clone(), CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert!(b2.cache_hit, "B second call must hit B's cache");

        // A's cache stats see exactly one miss + one hit — B's traffic
        // never touched A's cache.
        let a_stats = a.repo_stats_cache().stats();
        assert_eq!(a_stats.misses, 1, "A saw exactly one miss");
        assert_eq!(a_stats.hits, 1, "A saw exactly one hit");
        let b_stats = b.repo_stats_cache().stats();
        assert_eq!(b_stats.misses, 1, "B saw exactly one miss");
        assert_eq!(b_stats.hits, 1, "B saw exactly one hit");
    }

    // ─── Cut C4 — delivery-receipt JOIN gate (CEG §10.5.4) ─────────────
    //
    // End-to-end against in-memory SQLite with REAL hybrid signatures.
    // The load-bearing property is that the verify is a JOIN, not just a
    // sig-check: a correctly-signed receipt whose chunk_root is not a
    // published STH root (at tree_size >= k) is rejected.
    mod delivery_receipts {
        use super::*;
        use crate::federation::stream_receipt::{receipt_signing_bytes, DeliveryReceipt};
        use crate::federation::BlobStorage;
        use base64::engine::general_purpose::STANDARD as B64;
        use ed25519_dalek::Signer as _;

        /// Build a real hybrid-signed receipt. PQC signs
        /// `(canonical || classical_sig)` exactly as the verify path
        /// expects (mirrors `verify::hybrid::hybrid_round_trip_strict`).
        /// Returns the receipt plus the subscriber's (ed25519, ml_dsa_65)
        /// base64 pubkeys to seed into `federation_keys`.
        #[allow(clippy::too_many_arguments)]
        async fn signed_receipt(
            stream_id: &str,
            subscriber_key_id: &str,
            epoch: u64,
            k: u64,
            chunk_root: [u8; 32],
            ed_seed: u8,
            mldsa_seed: u8,
        ) -> (DeliveryReceipt, String, String) {
            use ciris_keyring::PqcSigner;
            let canonical =
                receipt_signing_bytes(subscriber_key_id, stream_id, epoch, &chunk_root, k);

            let sk = ed25519_dalek::SigningKey::from_bytes(&[ed_seed; 32]);
            let ed_sig_bytes = sk.sign(&canonical).to_bytes();
            let ed_pk = sk.verifying_key().to_bytes();

            let mut bound = canonical.clone();
            bound.extend_from_slice(&ed_sig_bytes);
            let mldsa =
                ciris_keyring::MlDsa65SoftwareSigner::from_seed_bytes(&[mldsa_seed; 32], "c4-test")
                    .expect("ml-dsa seed");
            let pqc_sig = mldsa.sign(&bound).await.expect("ml-dsa sign");
            let pqc_pk = mldsa.public_key().await.expect("ml-dsa pk");

            let receipt = DeliveryReceipt {
                stream_id: stream_id.to_owned(),
                subscriber_key_id: subscriber_key_id.to_owned(),
                epoch,
                k,
                chunk_root,
                signature: ciris_crypto::HybridSignature {
                    crypto_kind: ciris_crypto::CRYPTO_KIND_CIRIS_V1,
                    classical: ciris_crypto::TaggedClassicalSignature {
                        algorithm: ciris_crypto::ClassicalAlgorithm::Ed25519,
                        signature: ed_sig_bytes.to_vec(),
                        public_key: ed_pk.to_vec(),
                    },
                    pqc: ciris_crypto::TaggedPqcSignature {
                        algorithm: ciris_crypto::PqcAlgorithm::MlDsa65,
                        signature: pqc_sig,
                        public_key: pqc_pk.clone(),
                    },
                    mode: ciris_crypto::SignatureMode::HybridRequired,
                },
            };
            (receipt, B64.encode(ed_pk), B64.encode(&pqc_pk))
        }

        /// Seed a `federation_keys` row carrying BOTH pubkeys so the
        /// Strict hybrid verify resolves the subscriber.
        fn seed_subscriber_key(
            backend: &SqliteBackend,
            key_id: &str,
            ed_b64: &str,
            mldsa_b64: &str,
        ) {
            let conn = backend.conn_handle();
            let conn = conn.lock();
            conn.execute(
                "INSERT OR REPLACE INTO federation_keys (\
                    key_id, pubkey_ed25519_base64, pubkey_ml_dsa_65_base64, algorithm, \
                    identity_type, identity_ref, valid_from, registration_envelope, \
                    original_content_hash, scrub_signature_classical, scrub_key_id, \
                    scrub_timestamp, persist_row_hash\
                 ) VALUES (?1, ?2, ?3, 'hybrid', 'agent', ?1, \
                          '2026-01-01T00:00:00Z', '{}', x'00', '', ?1, \
                          '2026-01-01T00:00:00Z', '0')",
                rusqlite::params![key_id, ed_b64, mldsa_b64],
            )
            .expect("seed federation_keys");
        }

        /// Raw-insert a published STH row (the JOIN gate only reads
        /// `root_hash`; the STH's own validity is C1b's concern, tested
        /// there). `signature_blob` just satisfies NOT NULL.
        fn seed_published_sth(
            backend: &SqliteBackend,
            stream_id: &str,
            tree_size: i64,
            root_hash: [u8; 32],
        ) {
            let conn = backend.conn_handle();
            let conn = conn.lock();
            conn.execute(
                "INSERT INTO federation_stream_sth (\
                    stream_id, tree_size, epoch, root_hash, signed_at, \
                    producer_key_id, signature_blob, witness_signatures\
                 ) VALUES (?1, ?2, 0, ?3, '2026-01-01T00:00:00Z', \
                          'producer-key', x'00', '[]')",
                rusqlite::params![stream_id, tree_size, root_hash.to_vec()],
            )
            .expect("seed federation_stream_sth");
        }

        async fn fresh() -> SqliteBackend {
            let backend = SqliteBackend::open_in_memory().await.unwrap();
            backend.run_migrations().await.unwrap();
            backend
        }

        /// Positive: a correctly-signed receipt whose chunk_root is a
        /// published STH root (tree_size >= k) is accepted, listed, and
        /// is idempotent on re-PUT.
        #[tokio::test]
        async fn signed_receipt_against_published_root_is_accepted() {
            let backend = fresh().await;
            let stream_id = "stream-c4-ok";
            let root = [0x11u8; 32];
            let (receipt, ed_b64, mldsa_b64) =
                signed_receipt(stream_id, "sub-1", 0, 2, root, 0x10, 0x20).await;
            seed_subscriber_key(&backend, "sub-1", &ed_b64, &mldsa_b64);
            seed_published_sth(&backend, stream_id, 3, root); // tree_size 3 >= k 2

            backend
                .put_delivery_receipt(receipt.clone())
                .await
                .expect("receipt against a published root is accepted");

            let listed = backend
                .list_delivery_receipts_for(stream_id, 10)
                .await
                .unwrap();
            assert_eq!(listed.len(), 1);
            assert_eq!(listed[0].subscriber_key_id, "sub-1");
            assert_eq!(listed[0].k, 2);
            assert_eq!(listed[0].chunk_root, root);

            // Idempotent re-PUT (identical root) → Ok, still one row.
            backend
                .put_delivery_receipt(receipt)
                .await
                .expect("identical re-PUT is idempotent");
            let listed = backend
                .list_delivery_receipts_for(stream_id, 10)
                .await
                .unwrap();
            assert_eq!(listed.len(), 1, "idempotent re-PUT must not duplicate");
        }

        /// Negative 1 — phantom root: a correctly-signed receipt for a
        /// root that was NEVER published as an STH is rejected by the
        /// JOIN gate (the signature is valid; the root is not).
        #[tokio::test]
        async fn phantom_root_is_rejected() {
            let backend = fresh().await;
            let stream_id = "stream-c4-phantom";
            let published = [0x11u8; 32];
            let phantom = [0x22u8; 32];
            let (receipt, ed_b64, mldsa_b64) =
                signed_receipt(stream_id, "sub-1", 0, 2, phantom, 0x10, 0x20).await;
            seed_subscriber_key(&backend, "sub-1", &ed_b64, &mldsa_b64);
            // Publish a DIFFERENT root; the receipt's phantom root has no STH.
            seed_published_sth(&backend, stream_id, 3, published);

            let err = backend.put_delivery_receipt(receipt).await.unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                    if m.contains("unpublished root")),
                "phantom root must be rejected by the JOIN gate, got: {err:?}"
            );
        }

        /// Negative 2 — under-published tree: the root is published, but
        /// only at tree_size < k. Acknowledging chunk k against a tree
        /// that does not yet contain k is rejected.
        #[tokio::test]
        async fn tree_size_below_k_is_rejected() {
            let backend = fresh().await;
            let stream_id = "stream-c4-short";
            let root = [0x11u8; 32];
            let (receipt, ed_b64, mldsa_b64) =
                signed_receipt(stream_id, "sub-1", 0, 5, root, 0x10, 0x20).await;
            seed_subscriber_key(&backend, "sub-1", &ed_b64, &mldsa_b64);
            seed_published_sth(&backend, stream_id, 3, root); // tree_size 3 < k 5

            let err = backend.put_delivery_receipt(receipt).await.unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                    if m.contains("unpublished root")),
                "tree_size < k must be rejected, got: {err:?}"
            );
        }

        /// Negative 3 — bad signature: the receipt is signed by the WRONG
        /// subscriber key (the seeded federation_keys row is a different
        /// keypair). The sig gate rejects before the JOIN.
        #[tokio::test]
        async fn wrong_key_signature_is_rejected() {
            let backend = fresh().await;
            let stream_id = "stream-c4-badsig";
            let root = [0x11u8; 32];
            // Receipt signed by seed 0x10/0x20 ...
            let (receipt, _ed_b64, _mldsa_b64) =
                signed_receipt(stream_id, "sub-1", 0, 2, root, 0x10, 0x20).await;
            // ... but federation_keys carries a DIFFERENT keypair's pubkeys.
            let (_other, other_ed, other_mldsa) =
                signed_receipt(stream_id, "sub-1", 0, 2, root, 0x77, 0x88).await;
            seed_subscriber_key(&backend, "sub-1", &other_ed, &other_mldsa);
            seed_published_sth(&backend, stream_id, 3, root);

            let err = backend.put_delivery_receipt(receipt).await.unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                    if m.contains("signature verification failed")),
                "a signature from the wrong key must be rejected, got: {err:?}"
            );
        }

        /// Negative 4 — subscriber equivocation: two receipts at the same
        /// (stream, subscriber, k) committing to DIFFERENT roots (both
        /// published) → the second is rejected.
        #[tokio::test]
        async fn subscriber_equivocation_is_rejected() {
            let backend = fresh().await;
            let stream_id = "stream-c4-equiv";
            let root_a = [0x11u8; 32];
            let root_b = [0x33u8; 32];
            let (r_a, ed_b64, mldsa_b64) =
                signed_receipt(stream_id, "sub-1", 0, 2, root_a, 0x10, 0x20).await;
            // Same subscriber keypair, same k, different root → re-sign.
            let (r_b, _ed2, _mldsa2) =
                signed_receipt(stream_id, "sub-1", 0, 2, root_b, 0x10, 0x20).await;
            seed_subscriber_key(&backend, "sub-1", &ed_b64, &mldsa_b64);
            // Both roots are published so the JOIN gate passes for each;
            // the equivocation check is what must reject the second.
            seed_published_sth(&backend, stream_id, 3, root_a);
            seed_published_sth(&backend, stream_id, 4, root_b);

            backend
                .put_delivery_receipt(r_a)
                .await
                .expect("first receipt ok");
            let err = backend.put_delivery_receipt(r_b).await.unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                    if m.contains("equivocation")),
                "a different root at the same (stream, subscriber, k) must reject, got: {err:?}"
            );
        }
    }

    // ── v5.4.0 (CIRISPersist#198, CEG 1.0 §5.6.8.8.2) content-KEM identity ──

    /// §5.6.8.8.2 conformance: the minted content-KEM x25519 is a FRESH,
    /// independent key — never derived from the Ed25519 signing key — and
    /// the keypair is STABLE across calls (idempotent load_or_init), so
    /// peers' prior wraps are never orphaned.
    #[tokio::test]
    async fn content_kem_identity_is_fresh_independent_and_stable() {
        use crate::federation::blobs::BlobStorage;
        use base64::engine::general_purpose::STANDARD as B64;
        use base64::Engine as _;

        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();

        let first = backend.load_or_init_content_kem_identity().await.unwrap();
        // Well-formed: x25519 = 32 raw bytes, ML-KEM-768 = 1184 raw bytes.
        assert_eq!(B64.decode(&first.x25519_pubkey_b64).unwrap().len(), 32);
        assert_eq!(
            B64.decode(&first.ml_kem_768_pubkey_b64).unwrap().len(),
            ciris_crypto::ml_kem::ML_KEM_768_PUBKEY_LEN
        );

        // Stable across calls within a backend: same pubkeys back
        // (idempotent — re-minting would orphan peers' prior wraps).
        let second = backend.load_or_init_content_kem_identity().await.unwrap();
        assert_eq!(first.x25519_pubkey_b64, second.x25519_pubkey_b64);
        assert_eq!(first.ml_kem_768_pubkey_b64, second.ml_kem_768_pubkey_b64);

        // §5.6.8.8.2 independence: a SECOND, separate backend mints a
        // DIFFERENT content-KEM keypair — proving fresh CSPRNG generation,
        // not derivation from any shared/deterministic input.
        let other = SqliteBackend::open_in_memory().await.unwrap();
        other.run_migrations().await.unwrap();
        let other_id = other.load_or_init_content_kem_identity().await.unwrap();
        assert_ne!(
            first.x25519_pubkey_b64, other_id.x25519_pubkey_b64,
            "two independent mints must differ (fresh keygen, no derivation)"
        );
        assert_ne!(
            first.ml_kem_768_pubkey_b64, other_id.ml_kem_768_pubkey_b64,
            "two independent ML-KEM-768 mints must differ"
        );
    }

    // ── v9.1.0 (CC 1.13.3 / FSD §2.4, CIRISPersist#243) scope-blob store ──

    fn scope_record_id(seed: u8) -> [u8; 32] {
        [seed; 32]
    }

    #[tokio::test]
    async fn sqlite_put_scope_blob_round_trip() {
        use crate::federation::{BlobStorage, GroupDekRef};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let record_id = scope_record_id(0x11);
        let nonce = [0x22u8; 24];
        let ciphertext = b"caller-pre-encrypted-symbol-bytes".to_vec();
        let tag = [0x33u8; 16];
        backend
            .put_scope_blob(
                record_id,
                0,
                nonce,
                ciphertext.clone(),
                tag,
                GroupDekRef::new("community-x".into(), 7),
            )
            .await
            .expect("put_scope_blob");
        let got = backend
            .get_scope_blob(record_id, 0)
            .await
            .expect("get_scope_blob")
            .expect("present");
        assert_eq!(got.symbol_index, 0);
        assert_eq!(got.nonce, nonce);
        assert_eq!(got.ciphertext, ciphertext);
        assert_eq!(got.tag, tag);
        assert_eq!(got.group_dek_epoch, 7);
    }

    #[tokio::test]
    async fn sqlite_scope_blob_n_symbols_and_idempotent_reput() {
        use crate::federation::{BlobStorage, GroupDekRef};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let record_id = scope_record_id(0x44);
        const N: u16 = 20;
        for i in 0..N {
            backend
                .put_scope_blob(
                    record_id,
                    i,
                    [i as u8; 24],
                    vec![i as u8; 8],
                    [i as u8; 16],
                    GroupDekRef::new("community-y".into(), 3),
                )
                .await
                .unwrap();
        }
        // Re-put of an existing index is idempotent (first-write-wins): the
        // original ciphertext is preserved, no duplicate row.
        backend
            .put_scope_blob(
                record_id,
                5,
                [0xFFu8; 24],
                b"different-bytes".to_vec(),
                [0xFFu8; 16],
                GroupDekRef::new("community-y".into(), 99),
            )
            .await
            .unwrap();
        let symbols = backend
            .list_scope_blob_symbols(record_id)
            .await
            .expect("list");
        assert_eq!(symbols.len(), N as usize, "PK dedup: no extra row");
        for (i, s) in symbols.iter().enumerate() {
            assert_eq!(s.symbol_index, i as u16, "ordered by symbol_index ASC");
        }
        let s5 = backend.get_scope_blob(record_id, 5).await.unwrap().unwrap();
        assert_eq!(s5.ciphertext, vec![5u8; 8], "first write wins on re-put");
        assert_eq!(s5.group_dek_epoch, 3);
        assert_eq!(s5.nonce, [5u8; 24]);
    }

    #[tokio::test]
    async fn sqlite_scope_blob_read_bumps_last_accessed_at() {
        use crate::federation::{BlobStorage, GroupDekRef};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let record_id = scope_record_id(0x55);
        backend
            .put_scope_blob(
                record_id,
                0,
                [1u8; 24],
                vec![1u8; 4],
                [1u8; 16],
                GroupDekRef::new("community-z".into(), 0),
            )
            .await
            .unwrap();

        let read_last_accessed = || {
            let conn = backend.conn.clone();
            let rid = record_id.to_vec();
            move || -> String {
                let conn = conn.lock();
                conn.query_row(
                    "SELECT last_accessed_at FROM federation_scope_blobs \
                     WHERE record_id = ?1 AND symbol_index = 0",
                    rusqlite::params![rid],
                    |r| r.get::<_, String>(0),
                )
                .unwrap()
            }
        };
        let before = read_last_accessed()();
        tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        let _ = backend.get_scope_blob(record_id, 0).await.unwrap();
        let after = read_last_accessed()();
        assert!(
            after > before,
            "read must bump last_accessed_at (before={before}, after={after})"
        );
    }

    #[tokio::test]
    async fn sqlite_scope_blob_eviction_removes_lru_first() {
        use crate::federation::{BlobStorage, GroupDekRef};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let record_id = scope_record_id(0x66);
        // Admit 6 symbols; admitted_at == last_accessed_at on write, so the
        // staggered admission order IS the LRU order initially.
        for i in 0..6u16 {
            backend
                .put_scope_blob(
                    record_id,
                    i,
                    [i as u8; 24],
                    vec![i as u8; 4],
                    [i as u8; 16],
                    GroupDekRef::new("community-e".into(), 1),
                )
                .await
                .unwrap();
            tokio::time::sleep(std::time::Duration::from_millis(3)).await;
        }
        // Re-read the two oldest (0, 1) so they become the freshest and must
        // survive despite being admitted first.
        let _ = backend.get_scope_blob(record_id, 0).await.unwrap();
        tokio::time::sleep(std::time::Duration::from_millis(3)).await;
        let _ = backend.get_scope_blob(record_id, 1).await.unwrap();

        // Capacity = 3: evict the 3 coldest of the 6.
        let deleted = backend.evict_scope_blobs(3).await.expect("evict");
        assert_eq!(deleted, 3);
        let survivors: Vec<u16> = backend
            .list_scope_blob_symbols(record_id)
            .await
            .unwrap()
            .into_iter()
            .map(|s| s.symbol_index)
            .collect();
        assert_eq!(survivors.len(), 3);
        // 0 and 1 were re-read last → freshest → survive. 5 was admitted
        // last → also fresh → survives. 2,3,4 are the coldest → evicted.
        assert!(survivors.contains(&0), "re-read symbol 0 survives");
        assert!(survivors.contains(&1), "re-read symbol 1 survives");
        assert!(survivors.contains(&5), "newest-admitted symbol 5 survives");
        for cold in [2u16, 3, 4] {
            assert!(
                !survivors.contains(&cold),
                "LRU symbol {cold} must be evicted"
            );
        }
    }

    #[tokio::test]
    async fn sqlite_scope_blob_eviction_noop_under_capacity() {
        use crate::federation::{BlobStorage, GroupDekRef};
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        let record_id = scope_record_id(0x77);
        for i in 0..3u16 {
            backend
                .put_scope_blob(
                    record_id,
                    i,
                    [i as u8; 24],
                    vec![i as u8; 4],
                    [i as u8; 16],
                    GroupDekRef::new("community-f".into(), 0),
                )
                .await
                .unwrap();
        }
        let deleted = backend.evict_scope_blobs(10).await.unwrap();
        assert_eq!(deleted, 0, "no eviction when under capacity");
        assert_eq!(
            backend
                .list_scope_blob_symbols(record_id)
                .await
                .unwrap()
                .len(),
            3
        );
    }

    // ── #249 Cut B — enumerators + add_community_member (sqlite parity).

    /// Seed `n` user-role keys `pfx-0..` (trivially steward-bound) + a fresh
    /// migrated backend; returns the backend.
    async fn cutb_backend_with_users(pfx: &str, n: usize) -> SqliteBackend {
        use crate::federation::types::identity_type;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for i in 0..n {
            let id = format!("{pfx}-{i}");
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key_with_identity_type(&id, "user", &id, identity_type::USER),
                })
                .await
                .unwrap();
        }
        backend
    }

    fn cm(key_id: &str) -> crate::federation::CommunityMember {
        crate::federation::CommunityMember {
            key_id: key_id.into(),
            joined_at: "2026-06-04T00:00:00Z".parse().unwrap(),
            role: None,
        }
    }

    /// active_community_members: roster of 3, revoke 1 (effective now) →
    /// 2 active; lookup keeps the full roster.
    #[tokio::test]
    async fn active_community_members_subtracts_effective_revocation_sqlite() {
        use crate::federation::FederationDirectory;
        let backend = cutb_backend_with_users("acm", 3).await;
        // community key.
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("acm-comm", "acm-comm", "acm-comm"),
            })
            .await
            .unwrap();
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    "acm-comm",
                    fed_community(
                        "acm-comm",
                        "acm",
                        vec!["acm-0", "acm-1", "acm-2"],
                        crate::federation::types::consensus_protocol::FOUNDER_ONLY,
                        None,
                    ),
                ),
            )
            .await
            .unwrap();
        assert_eq!(
            backend
                .active_community_members("acm-comm")
                .await
                .unwrap()
                .len(),
            3
        );
        backend
            .put_community_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                    "acm-comm",
                    crate::federation::CommunityMembershipRevocation {
                        community_key_id: "acm-comm".into(),
                        removed_identity_key_id: "acm-1".into(),
                        removed_at: chrono::Utc::now(),
                        effective_at: chrono::Utc::now(),
                        reason: None,
                        witness_set: vec![],
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();
        let active = backend.active_community_members("acm-comm").await.unwrap();
        let keys: std::collections::HashSet<&str> =
            active.iter().map(|m| m.key_id.as_str()).collect();
        assert_eq!(active.len(), 2);
        assert!(!keys.contains("acm-1"));
        assert_eq!(
            backend
                .lookup_community("acm-comm")
                .await
                .unwrap()
                .unwrap()
                .members
                .len(),
            3
        );
    }

    /// active_family_members: a FUTURE-DATED revocation keeps the member;
    /// an effective one drops it (same shared fold).
    #[tokio::test]
    async fn active_family_members_future_revocation_keeps_member_sqlite() {
        use crate::federation::FederationDirectory;
        let backend = SqliteBackend::open_in_memory().await.unwrap();
        backend.run_migrations().await.unwrap();
        for k in ["afm-fam", "afm-carol", "afm-dave"] {
            backend
                .put_public_key(SignedKeyRecord {
                    record: fed_key(k, k, k),
                })
                .await
                .unwrap();
        }
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                "afm-fam",
                fed_family(
                    "afm-fam",
                    "fam",
                    vec!["afm-carol", "afm-dave"],
                    crate::federation::types::consensus_protocol::FOUNDER_ONLY,
                ),
            ))
            .await
            .unwrap();
        let rev = |member: &str, effective_at: chrono::DateTime<chrono::Utc>| {
            crate::federation::tier_ingest::test_support::sign_family_membership_revocation(
                "afm-fam",
                crate::federation::FamilyMembershipRevocation {
                    family_key_id: "afm-fam".into(),
                    removed_identity_key_id: member.into(),
                    removed_at: chrono::Utc::now(),
                    effective_at,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            )
        };
        // carol: future-dated → stays active. dave: effective now → drops.
        let future = chrono::Utc::now() + chrono::Duration::days(30);
        backend
            .put_family_membership_revocation(rev("afm-carol", future))
            .await
            .unwrap();
        backend
            .put_family_membership_revocation(rev("afm-dave", chrono::Utc::now()))
            .await
            .unwrap();
        let active = backend.active_family_members("afm-fam").await.unwrap();
        assert_eq!(
            active.len(),
            1,
            "future-dated member stays; effective drops"
        );
        assert_eq!(active[0].key_id, "afm-carol");
    }

    /// add_community_member: add → appears in lookup + active reader; re-add
    /// → idempotent (false, no dup).
    #[tokio::test]
    async fn add_community_member_grows_roster_idempotent_sqlite() {
        use crate::federation::FederationDirectory;
        let backend = cutb_backend_with_users("addc", 2).await;
        backend
            .put_public_key(SignedKeyRecord {
                record: fed_key("addc-comm", "addc-comm", "addc-comm"),
            })
            .await
            .unwrap();
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    "addc-comm",
                    fed_community(
                        "addc-comm",
                        "addc",
                        vec!["addc-0"],
                        crate::federation::types::consensus_protocol::FOUNDER_ONLY,
                        None,
                    ),
                ),
            )
            .await
            .unwrap();
        assert!(backend
            .add_community_member("addc-comm", cm("addc-1"))
            .await
            .unwrap());
        let active = backend.active_community_members("addc-comm").await.unwrap();
        let keys: std::collections::HashSet<&str> =
            active.iter().map(|m| m.key_id.as_str()).collect();
        assert!(keys.contains("addc-0") && keys.contains("addc-1"));
        assert!(backend
            .lookup_community("addc-comm")
            .await
            .unwrap()
            .unwrap()
            .members
            .iter()
            .any(|m| m.key_id == "addc-1"));
        // Idempotent re-add.
        assert!(!backend
            .add_community_member("addc-comm", cm("addc-1"))
            .await
            .unwrap());
        assert_eq!(
            backend
                .lookup_community("addc-comm")
                .await
                .unwrap()
                .unwrap()
                .members
                .iter()
                .filter(|m| m.key_id == "addc-1")
                .count(),
            1
        );
        // Unknown community.
        assert!(backend
            .add_community_member("no-such", cm("addc-0"))
            .await
            .is_err());
    }

    /// moderators_of: founder (authority root) + `delegates_to(moderate)`
